insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('EEB386H1', 'Diversity of Birds', '24L/24P', 'Diversity of Birds provides a general overview of bird biology and diversity, including bird origins and evolution, modern classification and diversity, flight evolution and mechanics, reproduction, ecology, and conservation. Labs focus on anatomy, functional morphology and field techniques that will be put into practice in a final field trip.', 'BIOD48H3/ BIO326H5', 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB388H1', 'Diversity of Mammals', '24L/36P', 'Lectures and laboratories examine the natural history, morphology, classification, evolutionary relationships, reproduction, biogeography, and conservation of mammals. Labs focus on the identification of mammals and their diverse morphological adaptations including mammals of Ontario.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB390H1', 'Vertebrate Paleontology: Major Transitions in Vertebrate History', '24L/18P', 'The evolutionary history of vertebrates is recorded in their fossil record. Lectures highlight the origin and radiation of major vertebrate clades, and emphasize key events in vertebrate history, notably major ecological and evolutionary transitions, and mass extinctions. Practicals (at the Royal Ontario Museum) explore fossils that exemplify these themes.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB263H1", "EEB267H1", "EEB362H1", "EEB382H1", "EEB384H1", "EEB386H1", "EEB388H1"]}]}'::jsonb),
    ('EEB397Y1', 'Research Project in Ecology and Evolutionary Biology', null, 'An intermediate research project requiring the prior consent of a member of the Department to supervise the project. The topic is to be one mutually agreed on by the student and supervisor. They must arrange the time, place, and provision of any materials and submit to the Undergraduate Office a signed form of agreement outlining details prior to being enrolled. This course is open to highly self-motivated students who are in their Third Year and have a strong interest in ecology and/or evolutionary biology. Students are required to write up the results of their research in a formal paper, often in the format of a research article, and may be required to present the results at a poster session and/or participate in an oral presentation. Students should contact their potential supervisors over the summer before classes begin in September. Information regarding how to apply and register for the course is available on the EEB website. Not eligible for CR/NCR option. Note: cannot enrol if already taken the fourth year research project course  EEB498Y1/ EEB499Y1.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('EEB398H0', 'Research Excursions', null, 'An instructor-supervised project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EEB398Y0', 'Research Excursion', null, 'An instructor-supervised group project in an off-campus setting. Details at: https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('EEB399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EEB399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EEB401H1', 'Marine Field Ecology', null, 'A two-week field course offered in Summer. The course will include activities in and around the ocean and its shorelines with lectures and seminars combined with intensive field work on different marine habitats – from rocky reefs to kelp forests – and organisms. Students will conduct independent research projects. Comfortable with swimming is expected of students. Students interested in taking an EEB field course apply directly to the department. Spaces for the course are limited, and student selection is based on a number of criteria that include:  background in EEB concepts and approaches (assessed through courses taken and grades); benefit of course to student progress in their program of study and for professional development (assessed through courses taken and the student statement in the application) interest and motivation for taking the course (assessed through the student statement in the application) Year of study, with more senior students given preference.  See Departmental website for details. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB403H1', 'Tropical Field Biology', null, 'A two-week field course introducing students to the diversity of biological communities in the tropics focusing on ecological and evolutionary interactions. Plant and animal communities of the South American tropics are compared and contrasted with temperate communities. Student research projects included. Fee for accommodations, food, within course travel, station fee, etc., will apply. Students interested in taking an EEB field course apply directly to the department. Spaces for the course are limited, and student selection is based on a number of criteria that include:  background in EEB concepts and approaches (assessed through courses taken and grades); benefit of course to student progress in their program of study and for professional development (assessed through courses taken and the student statement in the application) interest and motivation for taking the course (assessed through the student statement in the application) Year of study, with more senior students given preference.  See Departmental website for details. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB405H1', 'Temperate Field Biology', null, 'A two-week field course offered (in May or August) at U of T''s Koffler Scientific Reserve, King City, Ontario. Students learn the natural history of the region and conduct a field-based research project in ecology or evolutionary biology. A fee of $800 for accommodations, food, within course travel, station fee, etc. will apply. Students interested in taking an EEB field course apply directly to the department. Spaces for the course are limited, and student selection is based on a number of criteria that include:  background in EEB concepts and approaches (assessed through courses taken and grades); benefit of course to student progress in their program of study and for professional development (assessed through courses taken and the student statement in the application) interest and motivation for taking the course (assessed through the student statement in the application) Year of study, with more senior students given preference.  See Departmental website for details. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": ["BIO220H1"]}'::jsonb),
    ('EEB406H1', 'Inter-University Field Course', null, 'A two-week field course offered between May and August by another Ontario university (to various locations) as part of the Ontario Universities Program in Field Biology (OUPFB). The selection of field course modules are announced in January. For registration information and additional fees information consult the EEB website; fees from $350-5000 will be applied for field trip costs. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('EEB428H1', 'Global Change Ecology', '24L/24T', 'An examination of organism, population, and ecosystem responses to long-term environmental change occurring at the global scale, with emphasis on human caused perturbation to climate and the carbon, nitrogen, and hydrolic cycles and their ecological effects.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"credits": 1.0, "department": "EEB"}]}'::jsonb),
    ('EEB434H1', 'Marine Ecology', '24L/18P', 'This course explores the study of ecological processes in marine and coastal habitats. The course will cover processes operating from individuals to populations and communities to ecosystems, and spanning daily to decadal scales, and meters to global scales. The lab component of the course will apply lecture concepts and tools to specific case studies, which include hands-on activities/experiments/field excursions, and/or data synthesis and analysis. (Lab materials Fee: $26)', null, 4, '{"operator": "OR", "items": ["BIO220H1", {"operator": "AND", "items": ["BIO120H1", "ESS362H1"]}]}'::jsonb),
    ('EEB440H1', 'Ecology and Evolution of Plant-Animal Interactions', '24L/24T', 'Major concepts in ecology and evolution from the perspective of plant-animal interactions. The richness of interactions between plants and animals is explored including antagonistic interactions (e.g., herbivory), mutualistic interactions (e.g., pollination, seed dispersal, ant-plant associations), and interactions involving multiple species across trophic levels.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB225H1", "PSY201H1", "STA220H1", "STA257H1", "STA288H1", "GGR270H1", "HMB325H1"]}, {"operator": "OR", "items": ["EEB318H1", "EEB319H1", "EEB321H1", "EEB323H1", "EEB324H1", "EEB328H1", "EEB403H1", "EEB403H0", "EEB405H1", "EEB405H0", "EEB406H1", "EEB406H0", "EEB410H1", "EEB410H0"]}]}'::jsonb),
    ('EEB455H1', 'Genes, Environment and Behaviour', '18L/18S', 'An examination of the Gene-Environment Interplay perspective as sources of individual differences in behaviour, from both mechanistic and evolutionary viewpoints. Both historical and recent studies are used to illustrate important concepts in the field. Student-led discussions address the evidence base for these concepts.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"credits": 12.0, "department": null}, {"credits": 1.0, "department": "EEB"}]}'::jsonb),
    ('EEB458H1', 'Evolutionary Quantitative Genetics', '24L/12P', 'This course will cover quantitative genetic theory for inheritance and evolution of continuous traits over contemporary timescales. Students will learn how to estimate statistical quantities such as genetic variances and heritability using classical pedigree analysis and more recent genomic methods. In the lab component students will learn how to analyze quantitative genetic data sets using modern statistical software and methods.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["EEB225H1", "STA221H1", "STA238H1", "STA248H1", "STA255H1", "STA261H1", "STA288H1"]}, "EEB323H1"]}'::jsonb),
    ('EEB459H1', 'Population Genetics', '24L/12T', 'A focus on theoretical population genetics, using mathematical models to understand how different evolutionary forces drive allele frequency change. Students learn how to mathematically derive classic results in population genetics. Topics include drift, coalescence, the relationship between population and quantitative genetics, selection in finite populations, and mutation load. Offered in alternate years.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, "EEB323H1"]}'::jsonb),
    ('EEB460H1', 'Molecular Evolution and Genomics', '36L', 'Processes of evolution at the molecular level, and the analysis of molecular data. Gene structure, neutrality, nucleotide sequence evolution, sequence evolution, sequence alignment, phylogeny construction, gene families, transposition.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["CSC108H1", "EEB125H1", "EEB225H1", "EEB318H1", "EEB323H1", "EEB362H1"]}]}'::jsonb),
    ('EEB462H1', 'Phylogenetic Inference: Methods and Applications', '24L/24P', 'The representation of the evolutionary relationships in the form of phylogenetic trees has become a fundamental tool in many branches of biology. This course is an introduction to the core concepts and methods of phylogenetic reconstruction including parsimony, likelihood, and Bayesian techniques, as well as advanced topics such as divergence time estimation, species-tree inference, and species delimitation. Through a combination of lectures, discussions, and computer labs, students will master the theory and practice of phylogenetics.', 'BIO443H5', 5, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB225H1", "STA220H1", "STA247H1", "STA248H1", "STA261H1", "STA288H1", "GGR270H1", "PSY201H1"]}]}'::jsonb),
    ('EEB463H1', 'Computing Stochastic Models in Evolutionary Biology', '36L', 'Probability and stochasticity underlie our understanding of evolutionary and ecological processes, but many students don''t get to experience these concepts without a background in mathematics or computer science. This course explores the fundamentals of modelling and quantitative approaches in ecology, evolution, and organismal biology in an accessible way. We will cover the probabilistic foundations of ecological, evolutionary, and bioinformatic models and concepts by developing students'' proficiency at developing their own code from scratch.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["EEB318H1", "EEB323H1", "EEB324H1", "EEB362H1"]}, {"operator": "OR", "items": ["EEB125H1", "EEB225H1", "STA220H1", "STA237H1", "STA257H1", "STA288H1", "EEB313H1"]}]}'::jsonb),
    ('EEB465H1', 'Advanced Topics in Biodiversity Science and Conservation Biology', '36L', 'Biodiversity in the Anthropocene. This course links the biological and social sciences to identify human goals for future biodiversity, methods to achieve this biodiversity, and to understand key issues such as the end of the wild, ecosystem services as a unit of conservation, animal welfare as a moral responsibility, and GMOs as biodiversity. Practical training may be provided in identifying species at risk, and in applying ecological-economics to trade-off decisions.', null, 4, '{"operator": "AND", "items": ["BIO220H1", "EEB255H1", {"credits": 1.0, "department": "EEB"}]}'::jsonb),
    ('EEB466H1', 'Approaches to the Study of Biodiversity', '24L/24P', 'This course uses the collections, research, and public gallery areas of the Royal Ontario Museum to expose students to the ways in which biodiversity is discovered, analyzed, and interpreted in a museum setting. Topics include: morphological and molecular approaches, taxonomy, classification, bioinformatics and e-taxonomy, and the interpretation of biodiversity for the public.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB266H1", "EEB267H1", "EEB268H1", "EEB331H1", "EEB365H1", "EEB380H1", "EEB382H1", "EEB384H1", "EEB386H1", "EEB388H1"]}]}'::jsonb),
    ('EEB488H1', 'Research Issues in Ecology and Evolutionary Biology', '36L/36T', 'This course is taken concurrently by students who are enrolled in  EEB498Y1 Advanced Research Project in Ecology and Evolutionary Biology, and uses a combination of seminars, discussions, and presentations (including presentations by students) designed to cover issues commonly encountered when conducting research in ecology and evolutionary biology. Topics may include experimental design, effective use of statistics, scientific writing and publishing, public communication, ethics, and career development. Students will be required to attend weekly departmental seminars. This half-credit course runs from September to April and lectures meet in alternate weeks. Information regarding how to apply and enrol in the course is available on the EEB departmental website.', 'EEB499Y1', 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('EEB491H1', 'Seminar in Biodiversity and Conservation Biology', '24L', 'Seminar course in biodiversity and conservation biology, emphasizing critical thinking and the synthesis of ideas crossing disciplinary boundaries. Group discussions among peers, facilitated by faculty, and student presentations. Discussions include critical analysis of research and review articles in the primary literature, with a focus on recent developments in biodiversity science and conservation biology. Evaluation based on presentations, participation in class discussions, and written assignments. (Note: students may take this course only once)', 'EEB495H1', 4, '{"operator": "AND", "items": [{"credits": 1.0, "department": "EEB"}]}'::jsonb),
    ('EEB495H1', 'Seminar in Ecology and Evolutionary Biology', '24S', 'Seminar course in ecology and evolutionary biology, emphasizing critical thinking and the synthesis of ideas crossing disciplinary boundaries. Group discussions among peers, facilitated by faculty, and student presentations. Discussions include critical analysis of research and review articles in the primary literature. Evaluation based on presentations, participation in class discussions, and written assignments. (Note students may take this course only once.)', 'EEB491H1', 4, '{"operator": "AND", "items": [{"credits": 1.0, "department": "EEB"}]}'::jsonb),
    ('EEB497H1', 'Research Studies in Ecology & Evolutionary Biology', null, 'An independent studies half-credit course allowing students to produce a literature review, which is supervised by a faculty member in the Department of Ecology and Evolutionary Biology. Highly motivated fourth-year students will work closely with a supervisor and be required to write up the results of their research in a final research paper. Students should contact a potential supervisor well before classes begin in the fall, winter, or summer session. Students cannot take more than two independent research courses of EEB 497H1, 498Y1, and 499Y1, and the second project must be with a different supervisor. Students cannot take multiple EEB research courses concurrently. Information on how to apply for the course is available on the EEB website. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('EEB498Y1', 'Advanced Research Project in Ecology and Evolutionary Biology', null, 'An advanced research project (a literature review alone is not sufficient) requiring the prior consent of a member of the Department to supervise the project. The topic is to be one mutually agreed on by the student and supervisor. They must arrange the time, place, and provision of any materials and submit to the Undergraduate Office a signed form of agreement outlining details prior to being enrolled. This course is open only to highly self-motivated students who are in their Fourth-Year and have adequate background in ecology and/or evolutionary biology. Students are required to write up the results of their research in a formal paper, often in the format of a research article, and are also required to present the results at a poster session and/or oral presentation. The time commitment is approximately 8 hours per week. Students should contact their potential supervisors over the summer before classes begin in September. Information regarding how to apply and register for the course is available on the EEB website. Students in this course are also concurrently enrolled in  EEB488H1Y Research Issues in Ecology and Evolutionary Biology. Students cannot take multiple EEB research courses concurrently. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('EEB499Y1', 'Advanced Research Project in Ecology and Evolutionary Biology II', null, 'An advanced research project (a literature review alone is not sufficient) that allows students to do another independent project, supervision of which must be different from  EEB497H1/ EEB498Y1. It requires the prior consent of a member of the Department to supervise the project. The topic is to be one mutually agreed on by the student and supervisor. They must arrange the time, place, and provision of any materials and submit to the Undergraduate Office a signed form of agreement outlining details prior to being enrolled. This course is open only to highly self-motivated students who are in their Fourth Year and have adequate background in ecology and/or evolutionary biology. Students are required to write up the results of their research in a formal paper, often in the format of a research article, and are also required to present the results at a poster session and/or oral presentation. The time commitment is approximately 8 hours per week. Students should contact their potential supervisors over the summer before classes begin in September. Information regarding how to apply and register for the course is available on the EEB website. Students cannot take multiple EEB research courses concurrently. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["EEB497H1", "EEB498Y1"]}, {"credits": 14.0, "department": null}]}'::jsonb),
    ('EHJ352H1', 'Human Evolutionary Genomics', '24L/12T', 'Human genome diversity and evolution with a focus on current research. The course integrates applications of human evolutionary genomics to the understanding of human history and adaptation, the causes of disease, and genome structure and function. Topics include: comparative genomics, population genomics of adaptation, association mapping, polygenic scores, and repetitive/selfish DNA.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}]}'::jsonb),
    ('ENG100H1', 'Effective Writing', '36L', 'Practical tools for writing in university and beyond. Students will gain experience in generating ideas, clarifying insights, structuring arguments, composing paragraphs and sentences, critiquing and revising their writing, and communicating effectively to diverse audiences. This course may not be counted toward any English program.', null, 1, null::jsonb),
    ('ENG102H1', 'Literature and the Sciences', '36L', 'Literature has always provided a place for the imaginative exploration of science, technology, and the physical universe. For students interested in literary treatments of science and scientific problems, concerns, and methods. Assumes no background in the methods and techniques of literary scholarship. This course may not be counted toward any English program.', null, 1, null::jsonb),
    ('ENG110Y1', 'Narrative', '48L/24T', 'This course explores the stories that are all around us and that shape our world: traditional literary narratives such as ballads, romances, and novels, and also non-literary forms of narrative, such as journalism, movies, myths, jokes, legal judgments, travel writing, histories, songs, diaries, biographies.', null, 1, null::jsonb),
    ('ENG140Y1', 'Literature for our Time', '48L/24T', 'An exploration of how recent literature in English responds to our world. Includes poetry, prose, and drama by major writers of the twentieth century and emerging writers of the current century.', null, 1, null::jsonb),
    ('ENG150Y1', 'Literary Traditions', '48L/24T', 'An introduction to major authors, ideas, and texts that shaped and continue to inform the ever-evolving traditions of literature in English. Includes works and authors from antiquity to the nineteenth century such as the Bible, the Qur''an, Plato, Homer, Sappho, Virgil, Dante, Christine de Pizan, Shakespeare, Cervantes, Montaigne, Austen, Dostoevski.', null, 1, null::jsonb),
    ('ENG196H1', 'Cook the Books', '36S', 'If, as Brillat-Savarin so famously said, “you are what you eat”, then what are we? What do our eating choices reveal about us and what we value? In this class, we will examine stories about farming, cooking, and eating in order to understand how culture shapes culinary traditions and vice versa. But we don''t stop there: through cooking and eating together, we will create new stories about our food and our relationship to the earth that sustains us. Co-taught with a professional chef, this course combines literary and historical analysis with hands-on cooking classes, shared meals, and food-oriented field trips. Restricted to first-year students. Not eligible for CR/NCR option. An additional fee to cover food and field trip costs is required.', 'ENG197H1,  ENG198H1,  ENG199H1', 1, null::jsonb),
    ('ENG197H1', 'Time Travel and Narrative', '24S', 'From H.G. Wells to Star Trek to Bill and Ted''s Excellent Adventure, tales of time travelers remain captivating. What does our fascination with time travel tell us about storytelling and narrative? This course will explore the questions that time travel raises about narrative as well as history, temporality, subjectivity, and agency. We will look at examples of time travel in film, television, and books as well as philosophical and scientific writing about it. Restricted to first-year students. Not eligible for CR/NCR option.', 'ENG196H1,  ENG198H1,  ENG199H1', 1, null::jsonb),
    ('ENG198H1', 'Representing Disability', '24S', 'Understanding disability as a cultural concept—not a medical condition or personal misfortune—that describes how human variation matters in the world, this course asks: how do literary texts represent physical and intellectual disability? Reading drama, fiction, and poetry, we will consider how disability prompts new strategies of writing and thinking, in order to consider what new forms of representation disability can produce, and what the concept of disability can teach us about being human. We will consider literary, visual, performative, and performance-based possibilities for bodies and minds that resist normative structures, theorize ideas of access, cure, and care, and claim disability as enlivening identity. Restricted to first-year students. Not eligible for CR/NCR option.', 'ENG196H1,  ENG197H1,  ENG199H1', 1, null::jsonb),
    ('ENG199H1', 'Tree Stories', '24S', 'Trees are all around us. We climb them, tell stories about them, write on paper, at desks, in homes made from them. But most people tend to take them for granted. This course considers how we imagine trees in works of art and legend and what trees can teach us about our own place in the world. We will read stories and poems as well as exploring the trees around campus and the environment we share. Restricted to first-year students. Not eligible for CR/NCR option.', 'ENG196H1,  ENG197H1,  ENG198H1', 1, null::jsonb),
    ('ENG201H1', 'Reading Poetry', '36L', 'An introduction to poetry through a close reading of texts, focusing on its traditional forms, themes, techniques, and uses of language; its historical and geographical range; and its contemporary diversity.', 'ENG201Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG202H1', 'Introduction to British Literature I', '36L', 'An introduction to British literature, exploring works in poetry, prose, and drama from the medieval period to the end of the seventeenth century.', 'ENG202Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG203H1', 'Introduction to British Literature II', '36L', 'An introduction to British literature, exploring works in poetry, prose, and drama from the end of the seventeenth century into the twentieth century.', 'ENG202Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG210H1', 'Introduction to the Novel', '36L', 'An introduction to the novel as literary genre through a reading of five or six key novels from a range of periods and regions.', 'ENG210Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG213H1', 'The Short Story', '36L', 'This course explores shorter works of nineteenth- and twentieth-century writers. Special attention is paid to formal and rhetorical concepts for the study of fiction as well as to issues such as narrative voice, allegory, irony, and the representation of temporality.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG215H1', 'The Canadian Short Story', '36L', 'An introduction to the Canadian short story, this course emphasizes its rich variety of settings, subjects, and styles.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG220H1', 'Introduction to Shakespeare', '36L', 'An introduction to Shakespeare''s work through five or six representative plays. Readings may include non-dramatic poetry as well as plays.', 'ENG220Y1,  ENG320Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG234H1', 'Children''s Literature', '36L', 'A critical and historical study of poetry and fiction written for or appropriated by children, this course may also include drama or non-fiction and will cover works by at least twelve authors such as Bunyan, Stevenson, Carroll, Twain, Alcott, Nesbit, Montgomery, Milne, Norton, Fitzhugh.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG235H1', 'The Graphic Novel', '36L', 'An introduction to book-length sequential art, this course includes fictional and nonfictional comics, with a focus on formal properties such as narrative layout and text/art hybridity. Themes vary but may include superheroes; auto/biography; the figure of the outsider; women in comics; alienation and youth; and war reporting.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG237H1', 'Science Fiction', '36L', 'This course explores speculative fiction that invents or extrapolates an inner or outer cosmology from the physical, life, social, and human sciences. Typical subjects include AI, alternative histories, cyberpunk, evolution, future and dying worlds, genetics, space/time travel, strange species, theories of everything, utopias, and dystopias.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG239H1', 'Fantasy and Horror', '36L', 'This course explores speculative fiction of the fantastic, the magical, the supernatural, and the horrific. Subgenres may include alternative histories, animal fantasy, epic fantasy, the Gothic, fairy tales, magic realism, sword and sorcery, and vampire fiction.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG240Y1', 'Old English Language and Literature', '72L', 'Prepares students to read the oldest English literary forms in the original language. Introduces the earliest English poetry in a woman''s voice, expressions of desire, religious fervour, and the agonies of war. Texts, written 680 - 1100, range from the epic of Beowulf the dragon-slayer to ribald riddles.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG250H1', 'Introduction to American Literature', '36L', 'An introduction to American literature, exploring works in a variety of genres, including poetry, fiction, essays, and slave narratives.', 'ENG250Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG252H1', 'Introduction to Canadian Literature', '36L', 'An introduction to Canadian literature, exploring works in poetry, prose, and drama from early to recent times.', 'ENG252Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG253H1', 'Caribbean Literature', '36L', 'An introduction to Caribbean poetry, prose, and drama in English or translation.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG254H1', 'Introduction to Indigenous Literatures', '36L', 'An introduction to Indigenous writings in English, with significant attention to Indigenous literatures in Canada. The writings are placed within the context of Indigenous cultural and political continuity, linguistic and territorial diversity, and living oral traditions. The primary focus may be on contemporary Indigenous writing.', 'ENG254Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG269H1', 'English Literature and Chinese Translation', '36L', 'This course studies how works of English literature have been translated and presented in modern Chinese culture. It requires no background in translation or literary studies. Through exercises and workshops, students will be exposed to works by British, American, and Canadian authors. Students will engage with issues in translation studies and learn practical skills of translation from English to Chinese. Class will be taught primarily in English, supplemented by Mandarin. Assignments to be completed in English. Reading knowledge of Mandarin is required.', null, 2, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG270H1', 'Introduction to Colonial and Postcolonial Writing', '36L', 'In this course, we examine the colonial archive for its representations of race, indigeneity, sexuality, and capital accumulation. We familiarize ourselves with the aesthetic and political modes of resisting colonial power around the world. Besides literary texts, our objects of study may include photographs, film, and digital media.', 'ENG270Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG273H1', 'Queer Writing', '36L', 'Introducing a lesbian, gay, bisexual, trans, and queer tradition in literature and theory, this course explores classical, modern, postmodern, and contemporary literature, criticism, art, film, music, and popular culture.', 'ENG273Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG280H1', 'Critical Approaches to Literature', '36L', 'An introduction to the theory and practice of literary criticism. Focusing on a single text or small group of texts, students will gain experience with close reading and analysis, critical theory, research methods, and the conventions and skills particular to literary-critical writing.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG281H1', 'Writing About Literature', '24L/12T', 'An introduction to the skills and contexts that underlie university-level writing about literature. Students will analyze the style and mechanics of literary criticism in a variety of fields, including published essays by Department faculty. Guest speakers and writing-intensive tutorials will help students begin to join the critical conversation.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG285H1', 'The English Language in the World', '36L', 'This introductory course surveys transnational, regional, and social varieties of Later Modern English; the linguistic and social factors that have shaped them; their characteristic structures; and their uses in speech and in writing, both literary and non-literary.', null, 2, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG286H1', 'Literature and Data', '24L/12T', 'Geared toward the interests and aptitudes of humanities students, this course provides an accessible introduction to computer programming, statistics, and data science, and equips students with the practical and theoretical skills to engage critically with literary data and computation. What new insights about literary form, history, or culture might we glean from a spreadsheet of bestsellers, a database of fan fiction, or an archive containing more novels than any individual could ever read? What gaps exist in literary datasets, and what biases are enshrined in code? No programming or statistical experience required or expected.', 'CSC111H1,  CSC148H1,  STA130H1,  STA238H1,  STA248H1,  STA261H1,  GGR274H1,  EEB125H1', 5, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG287H1', 'The Digital Text', '24L/12T', 'This course explores the stakes and consequences of literature''s transition from printed to digital forms. How do digital and printed texts differ materially, and how does this affect literary form, authorship, consumption, reception — and society more broadly? What new expressive possibilities are present in "born digital" forms like webcomics, fan fiction, interactive fiction, and videogames? How do social media and online reading communities impact the way that literature is marketed and discussed? Will electronic archives make literature more accessible, or less? How do digital texts challenge existing definitions of what counts as "literature"?', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG289H1', 'Introduction to Creative Writing', '36L', 'An introduction to creative writing, especially poetry and short fiction, attending to conventions of literary forms and genres, as well as to writing strategies, techniques, and terminology.', 'ENG389Y1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG296Y0', 'Topics in English Literature', null, 'Content varies with Instructor. Offered by the Summer Abroad program, usually in Oxford, England.', null, null, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG297Y0', 'Topics in English Literature', null, 'Content varies with Instructor. Offered by the Summer Abroad program, usually in Siena, Italy.', null, null, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENG299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENG300H1', 'Chaucer', '36L', 'An in-depth study of Chaucer''s works, including The Canterbury Tales and some of his shorter works.', 'ENG300Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG301H1', 'Sixteenth-Century Literature', '36L', 'An overview of some of the major works in English, especially in poetry and prose, written mostly before 1600.', 'ENG302Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG302H1', 'Seventeenth-Century Literature', '36L', 'An overview of some of the major works in English, especially in poetry and prose, written mostly after 1600.', 'ENG302Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG303H1', 'Milton', '36L', 'Selections from Paradise Lost and other works.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG305H1', 'Swift, Pope, and Their Contemporaries', '36L', 'Selected works in prose and verse by Swift and Pope studied alongside works by their contemporaries. Topics may include the legitimacy of satire, the role of criticism, and the growing importance of writing by women.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG306H1', 'Restoration and Early-Eighteenth Century Literature', '36L', 'This course explores the literatures produced across roughly two generations following the Restoration of the Stuart monarchy in 1660, during which time literary patronage gradually gave way to an early print capitalism. What emerged from that context was an exciting period defined by great satires, often obscene imagery, experimental prose, and novel media. This course examines the era''s formal innovations while touching on a number of themes that remain pressing to this day, including questions of politics, religion, and power, the tension between classical tradition and scientific discovery, shifting categories of identity such as race, class, and gender, and censorship and the role of the arts in the public sphere. Authors studied may include Behn, Bunyan, Rochester, Dryden, Defoe, Haywood, Montagu, Pope, and Swift.', 'ENG306Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG307H1', 'Eighteenth-Century Literature', '36L', 'This course explores the literatures produced between the heyday of English neoclassicism in the early part of the eighteenth century and the eruption of Romanticism towards the century''s end. The period between those two moments was marked by a refinement of Georgian taste, by the controversies and advances of Enlightenment, by the flamboyant performance of sentimentality, and ultimately, by a protracted series of global conflicts and revolutions. This course traces these themes and others alongside a careful study of the formal innovations of the period, its shifting rhetorics, and central aesthetic debates. Authors studied may include Pope, Swift, Gray, Johnson, Sterne, Equiano, Barbauld, Cowper, Wollstonecraft, and Blake.', 'ENG306Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG308H1', 'Romantic Literature to 1812', '36L', 'This course introduces students to the earlier years of Romantic poetry and prose. Romanticism (roughly 1780-1832) was a time of intense intellectual, cultural, political and social activity. We will explore some of its many forms and themes, including such topics as the nature of self, human rights, nationalism, political revolution, the role of imagination, nature, poetic form, class, slavery, and abolition. Texts will include selections from authors such as William Wordsworth, Charlotte Smith, S.T. Coleridge, William Blake, Edmund Burke, Thomas Paine, Anna Barbauld, Mary Robinson, Olaudah Equiano, Ann Radcliffe.', 'ENG308Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG309H1', 'Romantic Literature after 1812', '36L', 'This course introduces students to the later years of Romantic poetry and prose. Romanticism (roughly 1780-1832) was a time of intense intellectual, cultural, political and social activity. We will explore some of its many forms and themes, including such topics as the nature of self, human rights, nationalism, political revolution, the role of imagination, nature, poetic form, class, slavery, and abolition. Texts will include selections from authors such as Percy Shelley, Mary Shelley, John Keats, Felicia Hemans, John Clare, Thomas De Quincey, Jane Austen, Mary Prince, Lord Byron, Letitia Landon.', 'ENG308Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG311H1', 'Medieval Literature', '36L', 'This course explores a selection of writings in early English, excluding those by Chaucer.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG320H1', 'Shakespeare I: Early Plays and Poems', '36L', 'An in-depth study of selected plays and poems to 1600, this course equips students to explore Shakespeare''s works in relation to genre, language, structure, and performance. The course considers how the early works engage with Elizabethan social, political, and cultural contexts, and introduces some current developments in Shakespeare studies.  ENG321H1 is a recommended complement to  ENG320H1.', 'ENG320Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG321H1', 'Shakespeare II: Later Plays and Poems', '36L', 'An in-depth study of selected plays and poems after 1600, this course equips students to explore Shakespeare''s works in relation to genre, language, structure, and performance. The course considers how the later works engage with Jacobean social, political, and cultural contexts, and introduces some current developments in Shakespeare studies.  ENG320H1 is a recommended complement to  ENG321H1.', 'ENG320Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG322H1', 'The Rise of the Novel', '36L', 'This course traces the emergence of the modern novel between the late seventeenth and early nineteenth centuries, with special attention to innovations and experiments in narrative form, the mingling of genres in the early novel, and the wide thematic range of the period''s fiction. The focus is both technical and thematic: on the formally self-conscious quality of much eighteenth-century narrative, and on novelists'' use of the genre to address a broad range of issues such as selfhood and subjective experience; local and national identities; race, gender, ethnicity, and class relations; urban experience and social change; sympathy and community; politics and empire. Authors studied may include Behn, Defoe, Haywood, Richardson, Fielding, Sterne, Smollett, Austen; some attention may also be paid to related genres (e.g. journalism, autobiography, diaries, letters) that influenced, and were influenced by, the themes and conventions of the emergent novel.', 'ENG322Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG323H1', 'Austen and Her Contemporaries', '36L', 'A study of selected novels of Jane Austen and of works by such contemporaries as Radcliffe, Godwin, Wollstonecraft, Wordsworth, Edgeworth, Scott, and Shelley, in the context of the complex literary, social, and political relationships of that time.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG324H1', 'Early Victorian Novels', '36L', 'British novels from the middle of the nineteenth century still speak to us—in part because so many of their concerns remain our concerns: questions of gender and sexuality, social class, and race and colonialism, among many others. In this course, we will read fiction that addresses those questions and, in the process, reshapes the very form of the novel. Reading fiction by authors such as Dickens, Brontë, and Gaskell, we will consider issues of class, identity, and self-making as they arise in first-person narratives, the industrial novel, and the beginnings of sensation fiction. This course concentrates on the novel as it developed over roughly the first half of the Victorian era and is envisioned as a complement to (though independent of)  ENG325H1 Late Victorian Novels.', 'ENG324Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG325H1', 'Late Victorian Novels', '36L', 'A time of social, political, and literary tumult, the late Victorian era witnessed the publication of novels that would come to be iconic. Discussions will highlight issues such as changing ideas of class, gender, and identity; the role of imperialism in Victorian culture; and the origins of detective fiction. We will also think through the relation between literary form and historical change, analysing how specific styles and genres emerged to treat specific political questions, such as empire, and scientific discoveries, such as evolution. This course is envisioned as a complement to (though independent of)  ENG324H1 Early Victorian Novels.', 'ENG324Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG328H1', 'Modern Fiction', '36L', 'The first half of the twentieth century was among the most vibrant and inventive in English-language fiction. This period of literary history unfolded during a time of rapid and radical change that saw the development of new communications technologies like the radio and cinema, the massive upheavals of two world wars, the decline of empire, and paradigm-crushing developments in thinking about gender, sexuality, psychology, philosophy, and science. This course explores how a diverse selection of writers responded to this world in flux — and how they sought to use literature to intervene in this world, including through techniques such as plural conceptions of the self, stream-of- consciousness, unreliable narration, and multiple perspectives.', 'ENG328Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG329H1', 'Contemporary British Fiction', '36L', 'This course explores six or more works by at least four British contemporary writers of fiction.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG330H1', 'Medieval Drama', '36L', 'Plays and other texts composed for live performance across the first millennium of English history, primarily 1300-1485; morality plays, biblical pageants, solo performances, large-scale spectacles, mummings, religious rituals, rude songs, recovered fragments. Basic training in reading/translating medieval English sources and in decoding early cues for staging.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG331H1', 'Drama 1485-1603', '36L', 'Plays and performance history across Britain, 1485 to 1603; the rise of London theatres and of named English and Scottish playwrights (Medwall, Redford, Marlowe, Shakespeare, etc.); anonymous sixteenth-century plays from Cheshire, Yorkshire, East Anglia, and Cambridgeshire; traces of lost performances in the archives.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG335H1', 'Drama 1603-1642', '36L', 'This course explores English drama from the death of Queen Elizabeth I to the closing of the theatres, with attention to such playwrights as Jonson, Middleton, Shakespeare, Webster.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG337H1', 'Drama 1660-1800', '36L', 'At least twelve plays, including works by Dryden, Wycherley, Congreve, and their successors, chosen to demonstrate the modes of drama practiced during the period, the relationship between these modes and that between the plays and the theatres for which they were designed.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG340H1', 'Modern Drama', '36L', 'A study of plays in English by such dramatists as Wilde, Yeats, Shaw, Synge, Glaspell, Hughes, O''Neill, as well as plays in translation by such dramatists as Ibsen, Chekhov, Strindberg, Pirandello.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG341H1', 'Post-Modern Drama', '36L', 'A study of plays by such dramatists as Beckett, Miller, Williams, Pinter, Soyinka, Churchill, with background readings from other dramatic literatures.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG347H1', 'Victorian Literature', '36L', 'This is a critical introduction to major genres of Victorian literature. It offers an opportunity to explore how novelists, poets, and non-fiction prose writers such as the Brontës, Dickens, Tennyson, Darwin, Robert Browning, J.S. Mill, Thomas Hardy, and Oscar Wilde respond to crisis and transition: the Industrial Revolution, the Idea of Progress, and the Woman Question. Other topics may include the Romantic inheritance, liberty and equality, theology and natural selection, empire and nation, Art for Art''s Sake, the Fin de siècle, and Decadence. The multi-genre setup of the course allows students to see how novels, poems, and non-fiction prose develop as individual genres and converse with each other in responding to the same issues. Authors and topics vary with the instructor.', 'ENG347Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG348H1', 'Modern Poetry to 1960', '36L', 'This course explores poems by the representative poets of the modern(ist) period, such as Thomas Hardy, W.B. Yeats, Robert Frost, Ezra Pound, T.S. Eliot, H.D., W.H. Auden, Elizabeth Bishop, e.e. cummings, Langston Hughes, and others. What is unique about this period is the co-presence of and tension between elements of the chronologically modern and the radically modern (i.e. "modernist"), embodied in perspectives and issues that continue to impact our contemporary era. Students will be intrigued by the depth of anxieties and the variety of opportunities inherent in modern and modernist poetry.', 'ENG348Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG349H1', 'Contemporary Poetry', '36L', 'Works by at least six contemporary poets, such as Ammons, Ashbery, Heaney, Hughes, Lowell, Muldoon, Plath.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG350H1', 'Early Canadian Literature', '36L', 'Writing in English Canada before 1914, from a variety of genres such as the novel, poetry, short stories, exploration and settler accounts, nature writing, criticism, First Nations cultural production.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG352H1', 'Canadian Drama', '36L', 'A study of major Canadian playwrights and developments since 1940, with some attention to the history of the theatre in Canada.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG353H1', 'Canadian Fiction', '36L', 'This course introduces advanced study of Canadian fiction through provocative examples from the ethnically, geographically, and aesthetically diverse range of fiction produced in Canada. It considers key Canadian novels and short stories in their literary, historical, and critical contexts. Discussion may include topics such as Indigenous fiction, settler constructions of Canada, the Canadian versions of modernism and postmodernism, and multicultural and diasporic narratives.', 'ENG353Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG354H1', 'Canadian Poetry', '36L', 'Beginning with movements and debates that shaped the modernist period, this course will introduce students to genres, forms, and themes that have inspired twentieth and twenty- first century poetry in English Canada. From imagist experimentation and lyric elegies to long poems, from concrete poetry to spoken word poems and, more recently, digital poetry, we will examine the role of poetry today in diverse social, cultural, and aesthetic contexts.', 'ENG354Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG355H1', 'Transnational Indigenous Literatures', '36L', 'A study of works by Indigenous writers from North America and beyond, with significant attention to Indigenous writers in Canada. Texts engage with issues of de/colonization, representation, gender, and sexuality, and span multiple genres, such as fiction, life writing, poetry, drama, film, music, and creative non-fiction.', 'ENG355Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG357H1', 'New Writing in Canada', '36L', 'Close encounters with recent writing in Canada: new voices, new forms, and new responses to old forms. Texts may include or focus on poetry, fiction, drama, non-fiction, or new media.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG358H1', 'Early African Canadian Literature', '36L', 'Black Canadian Literature (poetry, drama, fiction, non-fiction) from its origin in the African Slave Trade in the 18th century to its current flowering as the expression of immigrants, exiles, refugees and ex-slave-descended and colonial-settler-established communities. This half-course will focus on significant authors of the latter 20th century, such as Austin Clarke, Dionne Brand, Lorena Gale, Dany Laferriere, Djanet Sears, etc., while lectures will address the history and politics that inspire Canada''s most dynamic and relevant, diverse and radical, insightful and outspoken assembly of scribes.', 'ENG356Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG359H1', 'Later African Canadian Literature', '36L', 'Black Canadian Literature (poetry, drama, fiction, non-fiction) from its origin in the African Slave Trade in the 18th century to its current flowering as the expression of immigrants, exiles, refugees and ex-slave-descended and colonial-settler-established communities. This half-course will focus on established authors and significant anthologies of the early 21st century, such as Frankson''s Africanthology, Mason-John & Cameron''s The Great Black North, and works by Andre Alexis, Wayde Compton, Michael Fraser, Suzette Mayr, Zalika Reid-Benta, etc., while lectures will address the history and politics that inspire Canada''s most dynamic and relevant, diverse and radical, insightful and outspoken assembly of scribes.', 'ENG356Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG360H1', 'Early American Literature', '36L', 'This course explores writing in a variety of genres produced in the American colonies in the seventeenth and eighteenth centuries, such as narratives, poetry, autobiography, journals, essays, sermons, court transcripts.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG363H1', 'American Literature to 1900', '36L', 'This course explores American writing in a variety of genres from the end of the Revolution to the beginning of the twentieth century.', 'ENG363Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG364H1', 'American Literature 1900 to the present', '36L', 'This course explores twentieth-century American writing in a variety of genres.', 'ENG364Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG365H1', 'Contemporary American Fiction', '36L', 'This course explores six or more works by at least four contemporary American writers of fiction.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG367H1', 'African Literatures in English', '36L', 'What, if anything, is distinctively "African" in African texts; what might it mean to produce "African" readings of African literature? We address these, as well as other questions, through close readings of oral performances and literary and other cultural texts.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG368H1', 'Asian North American Literature', '36L', 'Literature and cultures of Asian Canadians and Asian Americans, including fiction, poetry, theory, drama, film, and other media.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG369H1', 'South Asian Literatures in English', '36L', 'Major authors and literary traditions of South Asia, with specific attention to literatures in English from India, Sri Lanka, Pakistan, Bangladesh, and the diaspora. The focus will be on fiction and poetry with some reference to drama.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG370H1', 'Postcolonial and Transnational Discourses', '36L', 'This course focuses on recent theorizations of postcoloniality and transnationality through readings of fictional and non-fictional texts, along with analyses of contemporary films and media representations.', 'ENG370Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG371H1', 'Topics in Indigenous, Postcolonial, Transnational Literatures', '36L', 'Sustained study in a topic pertaining to Indigenous, postcolonial, or transnational literatures. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG372H1', 'Topics in Indigenous, Postcolonial, Transnational Literatures', '36L', 'Sustained study in a topic pertaining to Indigenous, postcolonial, or transnational literatures. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG373H1', 'Topics in Pre-1800 British Literature', '36L', 'Sustained study in a topic pertaining to British literature before 1800. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG374H1', 'Topics in Pre-1800 British Literature', '36L', 'Sustained study in a topic pertaining to British literature before 1800. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG376H1', 'Topics in Theory, Language, Critical Methods', '36L', 'Sustained study in a topic pertaining to literary theory, critical methods, or linguistics. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG377H1', 'Topics in Theory, Language, Critical Methods', '36L', 'Sustained study in a topic pertaining to literary theory, critical methods, or linguistics. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG378H1', 'Special Topics', '36L', 'Sustained study in a variety of topics, including: Canadian literature, American literature, Post-1800 British literature, and genres or themes that span across nations and periods. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.  Note: An additional fee of $123 will apply to the "Cook the Books" subtitle offering.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG379H1', 'Special Topics', '36L', 'Sustained study in a variety of topics, including: Canadian literature, American literature, Post-1800 British literature, and genres or themes that span across nations and periods. Content varies with instructors. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG382H1', 'Literary Theory', '36L', 'This course explores contemporary literary theory, but may include related readings from earlier periods. Schools or movements studied may include structuralism, formalism, phenomenology, Marxism, post-structuralism, reader-response theory, feminism, queer theory, new historicism, psychoanalysis, postcolonial theory, critical race studies, and ecocriticism.', 'ENG382Y1', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG384H1', 'Literature and Psychoanalysis', '36L', 'An introduction to psychoanalysis for students of literature, this course considers major psychoanalytic ideas through close readings of selected texts by Freud. The course also explores critiques and applications of Freud''s work and examines a selection of literary texts that engage psychoanalytic theory.', 'ENG384Y1', 2, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG385H1', 'History of the English Language', '36L', 'This course explores English from its prehistory to the present day, emphasizing Old, Middle, and Early Modern English and the theory and terminology needed to understand their lexical, grammatical, and phonological structure; language variation and change; codification and standardization; literary and non-literary usage.', null, 2, '{"operator": "AND", "items": [{"credits": 2.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG387H1', 'Creative Writing: Creative Nonfiction', '36S', 'A course devoted to the study and production of creative nonfiction, with attention to such matters as literary style and rhetoric, authorial self-positioning, and political and ethical considerations. Genres to be considered may include journalism, criticism, essays, biography, memoir, and autotheory. Priority enrolment will be given to students in the Creative Writing Minor. Not eligible for CR/NCR option.', 'CRE279H1;  INI308H1 (Selected Topics in Writing and Rhetoric: Writing Literary Journalism), offered in Summer 2021;  WRR312H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, "ENG289H1"]}'::jsonb),
    ('ENG388H1', 'Creative Writing: Poetry', '36S', 'A course devoted to the craft of writing poetry, with attention to a range of forms, genres, styles, and compositional methods. The workshopping of student writing will take place alongside discussions of key texts in the field. Priority enrolment will be given to students in the Creative Writing Minor. Not eligible for CR/NCR option.', 'ENG389Y1,  CRE280H1,  ENG373H5,  ENGB60H3,  ENGC86H3', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, "ENG289H1"]}'::jsonb),
    ('ENG389H1', 'Creative Writing: Short Fiction', '36S', 'A course devoted to the craft of writing short fiction, with attention to matters such as genre, narratorial perspective, characterization, plot, style, and setting. The workshopping of student writing will take place alongside discussions of key texts in the field. Priority enrolment will be given to students in the Creative Writing Minor. Not eligible for CR/NCR option.', 'ENG389Y1,  CRE275H1,  ENG374H5,  ENGB61H3,  ENGC87H3,  WRR311Y1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, "ENG289H1"]}'::jsonb),
    ('ENG390Y1', 'Individual Studies', null, 'A scholarly project chosen by the student and supervised by a member of the staff. The form of the project and the manner of its execution are determined in consultation with the supervisor. Proposal forms and deadlines are available on the department website. Not eligible for CR/NCR option.', 'ENG392H1', null, '{"operator": "AND", "items": [{"credits": 3.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG392H1', 'Individual Studies', null, 'A scholarly project chosen by the student and supervised by a member of the staff. The form of the project and the manner of its execution are determined in consultation with the supervisor. Proposal forms and deadlines are available on the department website. Not eligible for CR/NCR option.', 'ENG390Y1', null, '{"operator": "AND", "items": [{"credits": 3.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('ENG394H1', 'Creative Writing: Special Topics', '36S', 'Sustained study and creative practice with respect to a topic pertaining to Creative Writing: e.g., writing for children; science fiction and fantasy; digital/interactive stories; writing across culture; writing and the environment. Content varies with instructors. Class format may include seminar discussion and a workshop devoted to student writing. See Department website for current offerings. Course may not be repeated under the same subtitle. Priority enrolment will be given to students enrolled in the Creative Writing Minor.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, "ENG289H1"]}'::jsonb),
    ('ENG398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENG398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENG399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENG399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENG400H1', 'Internship', '12L/96P', 'In this course, upper-year students will participate in partnership-based academic internships offered by a range of non-profit and for-profit organizations in a variety of cultural and commercial fields. Students will acquire practical and professional experience at the same time as they contribute their own critical and communicative skills in a workplace setting. The course will offer structured engagement with participating organizations across the city as well as 4-5 in-class meetings and a final written assignment. Students can expect to complete a range of 80-90 hours with a partner organization (8 hours a week for up to 12 weeks). Not eligible for CR/NCR. Admission to the course will be by application (including a short writing sample).', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "ENG202H1", "ENG203H1", "ENG250H1", "ENG252H1", {"credits": 2.0, "department": "ENG"}]}'::jsonb),
    ('ENG480H1', 'Advanced Studies Seminar', '24S', 'Seminars are designed to provide students with the opportunity to practice their skills of research and interpretation, and to participate in critical discussion, at a particularly advanced level. All seminars demand substantial class participation and most require an oral presentation. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": "ENG"}, "ENG202H1", "ENG203H1", "ENG250H1", "ENG252H1", {"credits": 9.0, "department": null}]}'::jsonb),
