    ('ENG489H1', 'Advanced Studies Seminar', '24S', 'Seminars are designed to provide students with the opportunity to practice their skills of research and interpretation, and to participate in critical discussion, at a particularly advanced level. All seminars demand substantial class participation and most require an oral presentation. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": "ENG"}, "ENG202H1", "ENG203H1", "ENG250H1", "ENG252H1", {"credits": 9.0, "department": null}]}'::jsonb),
    ('ENG497H1', 'Advanced Creative Writing Seminar: Literary Citizenship', '24S', 'A course examining efforts to build and sustain literary culture and literary communities through individual initiatives and collective efforts. Topics may include book reviewing, youth engagement, small presses, writers'' organizations, and the state''s role in the publishing industry. Priority enrolment will be given to students enrolled in the Creative Writing Minor.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "ENG289H1", {"credits": 1.5, "department": "ENG"}]}'::jsonb),
    ('ENG498H1', 'Advanced Creative Writing Seminar: Long-Form Writing', '24S', 'Students study and produce long-form creative work in a genre of their choice (the novella, short stories, the long poem) or in a genre determined by the professor. Beyond craft and literary analysis, this course develops capacities that writers need to cultivate for future success, such as idea-generation, persistence, independence, and creative problem-solving. Priority enrolment will be given to students enrolled in the Creative Writing Minor.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "ENG289H1", {"credits": 1.5, "department": "ENG"}]}'::jsonb),
    ('ENG499Y1', 'Advanced Research Seminar', '48S', 'A seminar designed to provide students with the opportunity to practice their skills of research and interpretation at a particularly advanced level, especially suited for students considering a graduate degree in English or a related discipline. The course is open to Year 4 students in English Specialist and Major programs who have achieved 80% in all English courses they have taken at the 200-level or above. Students also need 4.0 ENG credits (including  ENG202H1,  ENG203H1,  ENG250H1,  ENG252H1). Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "ENG202H1", "ENG203H1", "ENG250H1", "ENG252H1", {"credits": 2.0, "department": "ENG"}]}'::jsonb),
    ('ENT200H1', 'Introduction to Entrepreneurship', '24L', 'How can new ideas and technologies be transformed into valuable startups? This course introduces a strategic framework for innovation-driven entrepreneurs, focusing on the key choices new founders face. The course emphasizes balancing experimentation and learning with core strategic decisions to gain a competitive edge. Through interactive lectures, case studies, and exercises, students will learn how to apply an entrepreneurial strategy framework across various industries. This is a highly discussion-based course. Attendance and active participation are an important part of the assessment.', 'RSM100H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ENT391H1', 'Exploring New Ventures', '24L/96P', 'This experiential learning course allows students to explore the inner working of new ventures or other innovative organizations. The majority of the course consists of activities applying entrepreneurial concepts within a local organization, with oversight from the Centre for Entrepreneurship. In-class activities facilitate the application of entrepreneurial tools to develop the students'' entrepreneurial skills.', 'JPM400Y1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["ENT200H1", "RSM100H1", "MGT100H1"]}]}'::jsonb),
    ('ENT392H1', 'Creating New Ventures', '12L/48P', 'This experiential learning course allows students to explore the inner working of their new ventures. The majority of the course consists of activities applying entrepreneurial concepts within the student''s own venture, with oversight from the Centre for Entrepreneurship. In-class activities facilitate the application of entrepreneurial tools to develop the students'' entrepreneurial skills.', 'ENT392Y1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["ENT200H1", "RSM100H1", "MGT100H1"]}]}'::jsonb),
    ('ENV100H1', 'Introduction to Environmental Studies', '24L', 'An investigation of the relationship between human beings and their natural and built environments. This interdisciplinary course will draw from the sciences, social sciences and the humanities to explore major social, cultural, economic, regulatory, ethical, ecological and technological aspects of environmental issues.', null, 3, null::jsonb),
    ('ENV101H1', 'Confronting the Climate Crisis', '24L', 'This course is a comprehensive, interdisciplinary introduction to the climate crisis, suitable for any undergraduate student at U of T. The course examines the climate crisis from scientific, social, economic, political, and cultural perspectives, from the physical science basis through to the choices we now face to stabilize the climate system. The course uses a mixture of lectures, hands-on activities, group projects, online discussion, and guest speakers to give students a deeper understanding of climate change as a complex, interconnected set of problems, while equipping them with a framework to evaluate the choices we face as a society, and to cultivate a culture of hope in the face of a challenging future.', 'ENV194H1', 3, null::jsonb),
    ('ENV194H1', 'Topics in Climate Change', '24S', 'In this class we will discuss the underlying science of the climate system and also explore how this information is communicated effectively. Restricted to first-year students. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENV195H1', 'The Sustainability Transition', '24S', 'Can you imagine a sustainable future? What would it look like? How can we get there? We are often bombarded by negative images about our future and the future of the planet. In this seminar class we will explore what a sustainable world might look like and ways that we can get there. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ENV196H1', 'Environment, Culture and Film', '36S', 'This first-year foundation course will introduce students to the scope and seriousness of some of current ecological concerns, as well as some core principles and concepts in the field of the intersection of environment and culture, through the lens of feature films. Through journal reflections, class discussions and guided critical thinking exercises, and a paper, students will be able to build confidence and enthusiasm for further study in environmental studies, within a small seminar setting. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('ENV197H1', 'Idleness and the Environment: What Does Sustainable Work Mean?', '24S', 'In a fast-paced, high-tech world—and one that must rapidly decarbonize to address the climate crisis—the relationship between labour and environment is rapidly changing. This course explores the intersection of work and the environment, considering how ideas about leisure and idleness might offer new pathways for a more sustainable future. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ENV198H1', 'Environment & Mental Wellness', '24S', 'This foundations course is an introduction to Environmental Psychology and related disciplines. We will examine the mutual relationship between the human psyche and the environment, with a focus on mental wellness. Topics will include: psycho-evolutionary environments, place attachment and identity, neurological toxins and environmental health, the modern period, cultural perceptions on nature-psyche, climate anxiety and ecological grief, nature connectedness and restorative environments. As a foundations course, students will develop key academic skills such as academic literacy, communication and application, interdisciplinary critical thinking, as well as creative problem solving. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('ENV199H1', 'Debating & Understanding Current Environmental Issues', '2L', 'The course examines current environmental issues for which there is no easy answer or consensus position. For instance, to help solve climate change should we generate more electricity from nuclear power-plants, which have no greenhouse gas emissions? Or instead, should we phase out nuclear plants because of possible accidents, costs and radioactive wastes? The seminar examines the scientific and political aspects of such issues and debates the pros and cons of each. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ENV200H1', 'Assessing Global Change: Science and the Environment', '24L/4T', 'The perspective which scientists bring to the understanding and resolution of environmental concerns having global implications: atmospheric systems and climate change, the biosphere and conservation of biodiversity. This living things and their environment breadth course is intended to fulfill the environmental literacy requirement for students in the BA programs of the School of the Environment or the living things and their environment breadth course requirement for Commerce, Humanities and Social Science students', 'BIO120H1,  EEB208H1', 4, null::jsonb),
    ('ENV221H1', 'Multidisciplinary Perspectives on Environment', '24L/4T', 'One of two foundation courses for the School''s undergraduate program. Introduces students to ways in which different disciplines contribute to our understanding of environment. Instructors and guest lecturers are drawn from the sciences, social sciences and the humanities and will present subject matter, assumptions, conceptualizations and methodologies of their disciplines.', 'TRN140Y1,  TRN141Y1', null, null::jsonb),
    ('ENV222H1', 'Pathways to Sustainability: An Interdisciplinary Approach', '24L/12T', 'ENV222H1 explores the concept and practice of sustainability by integrating scientific, technological, economic, political, psychological, historical, and ethical perspectives. The course begins by analyzing the challenges posed by the ecological crisis, including its historical roots. It then goes on to explore and evaluate a variety of approaches, strategies, and actions—at a personal, local, national, and global scale—that could move us towards authentic sustainability.', 'TRN140Y1,  TRN141Y1', 3, null::jsonb),
    ('ENV223H1', 'Fundamental Environmental Skills', '24L', 'The practical, interdisciplinary and controversial nature of environmental issues, as well as the uncertainty that surrounds measures to address them demand mastery of a particular range of skills by environmental students. This course teaches the fundamental research, analysis and presentation skills required for effective environmental work. This course is for students enrolled in the Environmental Studies Major program, or permission of the Undergraduate Associate Director.', 'GGR271H1', null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ENV237H1', 'Physics of the Changing Environment A', '24L/24P', 'The course will cover basic physics of environmental processes and of measurement techniques in the atmosphere, the ocean, lake-land-forest systems, and other biological systems. It will place its work in the context of climate change and other aspects of environmental change. This course is solely intended for students who have NOT completed a previous first year physics core course, who are in one of the following programs: Environmental Science Major or Minor, Environmental Geosciences Specialist or Earth and Environmental Systems Major.', 'ENV238H1,  PHY131H1/ PHY132H1/ PHY151H1/ PHY152H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT135H1", "MAT136H1", "MAT137Y1", "MAT157Y1", "JMB170Y1"]}, {"operator": "OR", "items": ["CHM136H1", "CHM138H1", "CHM135H1", "CHM139H1", "CHM151Y1"]}]}'::jsonb),
    ('ENV238H1', 'Physics of the Changing Environment B', '24L/24P', 'The course will cover basic physics of environmental processes and of measurement techniques in the atmosphere, the ocean, lake-land-forest systems, and other biological systems. It will place its work in the context of climate change and other aspects of environmental change. This course is solely intended for students who have completed a previous first year physics core course, who are in one of the following programs: Environmental Science Major or Minor, Environmental Geosciences Specialist or Earth and Environmental Systems Major.', 'ENV237H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT135H1", "MAT136H1", "MAT137Y1", "MAT157Y1", "JMB170Y1"]}, {"operator": "OR", "items": ["CHM136H1", "CHM138H1", "CHM135H1", "CHM139H1", "CHM151Y1"]}, {"operator": "OR", "items": ["PHY131H1", "PHY132H1", "PHY151H1", "PHY152H1"]}]}'::jsonb),
    ('ENV262H1', 'The Science of Energy in the Environment', '24L/12T', 'Energy is a fundamental organizing principle of Nature. It has a central role in the origin and evolution of the universe, and is the basis of the ecosystem of the Earth and of technology and the world economy. This course will explore the science of energy in all its forms. ( ENV262H1 is primarily intended as a Breadth Requirement course for students in the Humanities and Social Sciences.)', 'ENV346H1, ( PHY131H1,  PHY132H1,  PHY151H1,  PHY152H1 or equivalent, taken previously or concurrently)', 5, null::jsonb),
    ('ENV281H1', 'Special Topics in Environment', '24L', 'Special topics course designed for students in School of the Environment programs. Content in any given year depends on instructor. See School of the Environment website for more details.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ENV282H1', 'Special Topics in the Environment', '24L', 'Special topics course designed for students in School of the Environment programs. Content in any given year depends on instructor. See School of the Environment website for more details.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ENV299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENV299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENV301H1', 'Critically Thinking about Climate Solutions', '24L/12T', 'This course builds on what you have learned about the nature of the climate crisis ( ENV101H1), science of global change ( ENV200H1) and the sustainability transition ( ENV222H1). It will provide students with a comprehensive framework for evaluating and comparing climate solutions. The course will begin with an assessment of the scale and urgency of the climate crisis as a basis for assessing solutions. Students will learn how to evaluate climate solutions from the point of view of feasibility, scale, timeframe, risk, equity, governance, likely co-benefits, and climate justice. Using a systems thinking approach, students will use a mix of qualitative and quantitative reasoning to assess current and proposed climate solutions. The course will also address current controversies and ethical dilemmas in addressing climate change, including mitigation versus adaptation, incrementalism versus system change, decoupling versus degrowth, greenwashing, and the ethics of geoengineering.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "ENV101H1", {"operator": "OR", "items": ["ENV200H1", "ENV237H1", "ENV238H1"]}, "ENV222H1"]}'::jsonb),
    ('ENV307H1', 'Urban Sustainability', '18L/18P', 'This course critically examines the concept of urban sustainability in theory and application. Case studies of ongoing urban sustainability programs in the developed and developing world help students assess the successes and failures of these programs. The course also examines the current state of research and implementation efforts toward urban sustainability. Toronto''s urban sustainability and sustainable needs will be investigated through the use of Geographic Information Systems (GIS) during the course (previous experience with GIS is not required).', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV316H1', 'Laboratory and Field Methods in Environmental Science', '12T/36P', 'This course focuses on methods of sampling and analyzing natural air, water and solid Earth materials for physical, chemical and biological properties that are relevant to current environmental issues. It will integrate approaches from chemistry, physics, geology and biology, and cover techniques in field sampling, laboratory analyses and analyses of large environmental data sets. Basic concepts related to quality control will be emphasized throughout the course: sample collection and storage methods, calibration of field and lab instruments, analyses in complex matrices, errors (accuracy, precision), and detection limits. This course is for students enrolled in the Environmental Science Major program, or permission of the Undergraduate Associate Director. A fee of $26 will be charged for lab supplies, lab instrument charges and technical services.', 'ESS425H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["EEB240H1", "ENV234H1"]}, {"operator": "OR", "items": ["CHM210H1", "ENV237H1", "ENV238H1"]}, {"operator": "OR", "items": ["STA220H1", "STA288H1", "EEB225H1", "GGR270H1"]}]}'::jsonb),
    ('ENV320H1', 'National Environmental Policy', '24L/12T', 'Examines ways in which governments develop and implement policy to protect the environment within their borders. Primarily Canada, plus comparisons with other countries. The focus is upon the politics of environmental policy making, which is understood by examining the interests and powers of the relevant state and non-state actors.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV322H1', 'International Environmental Policy', '24L/12T', 'Examines the ways in which states negotiate and implement international agreements addressing global environmental issues, such as the United Nations Framework Convention on Climate Change. Focus is upon factors which determine the efficacy of multilateral environmental agreements and the prospects for stronger global environmental governance.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV323H1', 'Ontario Environmental Policy', '24S', 'Introduces students to public policy and institutional foundations of public policy in Canada, with an emphasis on environmental policy in Ontario. Provides an insiders perspective on how environmental policy has been developed in Ontario.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV330H1', 'Waste Not: Faith-Based Environmentalism', '24L', 'This course explores religious environmentalism, its proponents and opponents, and its core values within the Abrahamic faiths of Judaism, Christianity and Islam. Religious environmentalists have used teachings from sacred texts as exemplars of sustainability. Some, however, claim that these texts teach domination, anthropocentrism and hierarchical values. Looking at a range of worldviews, we focus on the topics of wastefulness, consumption, and simplicity. Readings about barriers, motivations, and values that inform environmental behaviour are complemented with field trips to places of worship where we will hear religious leaders speak about the environmental initiatives undertaken in their communities and see sacred spaces.', 'ENV382H1 (Special Topics in Environment: Waste Not, Want Not: Stories of Wastefulness in Religion & Society), offered in Winter 2018, Fall 2018, and Winter 2020', 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV333H1', 'Ecological Worldviews', '24L/10T', 'Approaches to environmental concerns are often marked by assumptions that reflect distinct worldviews positing particular understandings of the role of the human with respect to nature. This course explores sundry economic, political, scientific, religious, and moral worldviews pertaining to the environment, including environmental ethics, Gaia, ecofeminism, scientific cosmology, and indigenous perspectives.', null, 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV335H1', 'Environmental Design', '18L/18P', 'Environmental design, in the context of this course, refers to design strategies that account for the ability of supporting ecosystems to continue to meet human needs and those of other lifeforms without diminishing biological diversity or environmental quality. This course takes a hands-on approach to investigating several environmental design issues: climate-responsive design, energy consumption, health and comfort, natural lighting and ventilation, and water management. Students will build up a design of a net-zero carbon residential building through several instructive design exercises during the semester, including hands-on measurement and calculation activities.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV336H1', 'Ecology in Human-Dominated Environments', null, 'A two week course offered at a Southern Ontario field station during late summer. Introduction to im-pacts of humans on semi-natural and human-dominated environments of southern Ontario and over-view of the most commonly used assessment tools for states of ecosystems. These environments play important roles in terms of ecosystem services.', null, 4, null::jsonb),
    ('ENV337H1', 'Human Interactions with the Environment', '24L/12P', 'The impact of 7 billion people on the planet is enormous and challenges future generations. What are these impacts today and in future? What solutions and tools can avert societal collapse? Using an integrated and interdisciplinary systems approach, we explore problems and solutions to the earth''s limits to growth.', null, null, '{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM210H1", {"operator": "OR", "items": ["EEB240H1", "ENV234H1"]}, {"operator": "OR", "items": ["ENV237H1", "ENV238H1"]}, "ESS262H1"]}, {"operator": "AND", "items": [{"operator": "OR", "items": ["ENV221H1", "ENV222H1", "EEB240H1", "ENV234H1"]}, "BIO220H1", {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}]}'::jsonb),
    ('ENV338H1', 'Environmental Research Data and Decision-making', '24L/12T', 'Understanding the natural world and human perturbations to it requires data. All data has inherent biases and constraints. In this class we will explore the world of environmental data from the perspective of those interested in affecting positive change. The class will use case studies and current research to explore topics such as: How do environmental scientists design studies or experiments to answer specific questions? How do we characterize the limitations of the data we have and work within these constraints to answer scientific questions and make informed and meaningful decisions?', 'None', null, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}, "ENV223H1"]}'::jsonb),
    ('ENV341H1', 'Environment and Health', '24L', 'Examination of the linkages between human health and environment using an interdisciplinary, planetary health lens. Addresses basic public health and toxicological principles. Case studies are examined to highlight the multifaceted ways health and environment are interconnected and to understand key factors modulating environmental exposures and health outcomes in various populations.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ENV221H1", "ENV222H1", "BIO230H1", "BIO255H1"]}, {"credits": 8.0, "department": null}]}'::jsonb),
    ('ENV342H1', 'Ecology of the Mind', '24L', '“Ask not what is inside your head, but what your head is inside of.” – James Gibson. This course will explore how environmental settings shape our psyche: cognition, emotions, perceptions, behaviour, and wellbeing. It approaches the mind as embodied, socio-ecologically situated, and enacted. The course title is inspired by Gregory Bateson''s “ecology of mind” theory, which views the psyche as part of a relational network with the material world that, like biological ecosystems, will interact, adapt and evolve over time. Students will uncover how natural settings enhance sense of security, curiosity, connectedness and clarity, and how nature enhances systems thinking when we attend to its patterns of relationship. Students will understand and experience nature-based systems thinking that inspires more relational, interconnected and process-oriented perception. The course will highlight the psychological losses associated with environmental degradation, and how the benefits of above can be enhanced through nature-based mindfulness and collective environmental engagement.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ENV200H1", "ENV221H1", {"operator": "AND", "items": ["TRN140Y1", "TRN141Y1"]}, "BIO120H1", "PSY100H1"]}, {"credits": 9.0, "department": null}]}'::jsonb),
    ('ENV346H1', 'Terrestrial Energy Systems', '36L/24T', 'Various earth systems for energy transformation, storage and transport are explored. Geological, hydrological, biological, cosmological and oceanographic energy systems are considered in the context of the Earth as a dynamic system, including the variation of solar energy received by the planet and the redistribution of this energy through various radiative, latent and sensible heat transfer mechanisms. It considers the energy redistribution role of large-scale atmospheric systems, of warm and cold ocean currents, the role of the polar regions, and the functioning of various hydrological systems. The contribution and influence of tectonic systems on the surface systems is briefly introduced, as well the important role of energy storage processes in physical and biological systems, including the accumulation of fossil fuel reserves.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "JMB170Y1"]}, {"operator": "OR", "items": ["BIO120H1", "CHM136H1", "CHM138H1", "CHM135H1", "CHM139H1", "CHM151Y1", "PHY131H1", "PHY132H1", "PHY151H1", "PHY152H1"]}]}'::jsonb),
    ('ENV347H1', 'The Power of Economic Ideas', '24L', 'This course examines the power of economic ideas in effecting environmental change. Topics include the relation of ecological economics to mainstream economics, as well as the role of financial incentives to move the environmental agenda forward.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV350H1', 'Energy Policy and Environment', '24L', 'The course addresses: (1) physical, technological and economic aspects of energy and electricity systems and their associated environmental impacts; (2) current international, Canadian and Ontario energy policy; (3) technological, economic and political factors influencing policy which could significantly reduce environmental impacts of energy use.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV360H1', 'Is the Internet Green?', '36L', 'The Internet has deeply penetrated most aspects of society and yet we are remarkably unreflective about its impacts and sustainability. This course challenges students to critically evaluate evidence regarding the environmental and social impacts of the Internet and how the Internet contributes (or not) to goals of environmental sustainability.', 'ENV261H1', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV361H1', 'Social Media and Environmentalism', '24L/12T', 'This course examines the impacts of the internet on environmental thinking and policy-making. Topics include the use of social media as a tool for community-building and collaborative design, the sharing economy, online protest movements, mass surveillance and its implications, and the impact of misinformation on climate denialism.', 'BIG102Y1,  ENV381H1 if taken in 2015-16 or 2016-17', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('ENV362H1', 'Energy & Environment: Transitions in History', '36L', 'An exploration of the interactions between humans and their environments in the Holocene, focusing on the contexts and consequences of changes in energy technologies. Includes consideration of changes in food production and processing, transport and power generation technologies from the adoption of agriculture to the twentieth century.', 'HPS307H1,  HIS300H1', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('ENV381H1', 'Special Topics in Environment', '24L', 'Special topics course designed for students in School of the Environment programs. Topics vary based on the year offered. See the School of the Environment website for more details.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('ENV382H1', 'Special Topics in Environment', '24L', 'Special topics course designed for students in School of the Environment programs. Content in any given year depends on instructor. See School of the Environment website for more details.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('ENV395Y0', 'Special Topics Field Course', '48S', 'This course examines fundamental concepts in ecology, evolution, biodiversity, geology and conservation biology through lectures and fieldwork in highland, tropical and island ecosystems in Ecuador. The complex relations between these environments and the people who depend on them will also be examined through analysis of the social, cultural, and economic transformations that have taken place in recent years. Suitable for all School of the Environment programs.', null, 3, null::jsonb),
    ('ENV396H0', 'Special Topics Field Course', null, 'This course examines Australia''s environmental, wildlife and conservation issues from an interdisciplinary perspective. In consideration of these issues, Australia''s unique flora and fauna are examined through lectures and fieldwork in the various climatically varied regions of Australia that are visited throughout the course.', null, null, null::jsonb),
    ('ENV396Y0', 'Special Topics Field Course', null, 'This course examines Australia''s environmental, wildlife and conservation issues from an interdisciplinary perspective. In consideration of these issues, Australia''s unique flora and fauna are examined through lectures and fieldwork in the various climatically varied regions of Australia that are visited throughout the course.', null, 4, null::jsonb),
    ('ENV397Y0', 'Costa Rica: A Living Laboratory for Sustainability in Practice', '48L', 'Since abolishing its army in 1948, Costa Rica has prioritized healthcare, education, conservation, and sustainability. As a result, despite a modest per capita income, it has a high human development index and a relatively low ecological footprint (one quarter of Canada''s). By some measures, it may also be the happiest country in the world. During this course, students will learn how this came about while exploring concrete sustainability initiatives in areas related to education, environmental ethics, food production, forest conservation, and energy while also examining current challenges related to transportation, democracy, migration, and poverty. In so doing, students will gain insights into how more just, sustainable, and peaceful societies might be created in practice.', null, 3, null::jsonb),
    ('ENV398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENV398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENV399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENV399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ENV411H1', 'Sustainability Thinking', '24L/6T', 'This capstone course for the Certificate in Sustainability will build on the guiding sustainability principles and journal reflections that began in in the foundational course,  ENV222H1, and require students to reflect on the entirety of their sustainability education and experience.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ENV222H1", {"operator": "AND", "items": ["TRN140Y1", "TRN141Y1"]}]}, {"credits": 12.0, "department": null}]}'::jsonb),
    ('ENV421Y1', 'Community Research for Social & Environmental Change', '24L', 'This research course will provide students with an opportunity to engage in an action-focused, community-based group research project. This course is restricted to students enrolled in a program or certificate at the School of the Environment, or special permission of the Undergraduate Associate Director.', 'ENV421H1', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV422H1', 'Environmental Law', '24S', 'An introduction to environmental law for students in Environmental Studies; legal methods available to resolve environmental problems and the scope and limits of those methods; common law and statutory tools as well as environmental assessment legislation; the problem of standing to sue and the limits of litigation.', null, 3, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV430H1', 'Community Research in Environment and Faith', '24L', 'Faith-based environmentalism is rarely part of sustainability discourse but could provide opportunities to engage people in new ways. This community engaged research course explores the richness and complexity of faith-based environmentalism. Time in the classroom will be spent building knowledge of the discipline through the discussion of theories and ideas, acquiring research skills, and unpacking field experiences. Time in the field will be spent engaging with the work of community partners and learning from them. The course is designed to bridge classroom knowledge with field experiences that allow for critical reflection and creative expression.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('ENV431H1', 'Urban Sustainability & Ecological Technology', '24L', 'Ecological technology or green infrastructure encompasses those technologies that incorporate ecosystems to replace mechanical or non-living components in a machine or a piece of infrastructure. Complex systems theory and second-law thermodynamics are used as a template to explore concepts of urban sustainability, and the role of ecological technology in this context.', null, 4, '{"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}'::jsonb),
    ('ENV432H1', 'Urban Ecology', '24L/12S', 'The ecology of urban areas through consideration of the biological and physical environments, in particular how the human-constructed environment alters pre-existing biophysical conditions and interactions. Encompasses a comparative perspective to study the development of these emerging ecosystems of increasing importance given global urbanization. Saturday field trip using local transit.', null, 4, '{"operator": "AND", "items": ["BIO220H1", {"operator": "OR", "items": ["EEB319H1", "EEB321H1", "EEB365H1"]}]}'::jsonb),
    ('ENV440H1', 'Professional Experience Course', '10S', 'Regular academic seminars complement work placement of 70-80 hours at an organization involved with environmental work. The course enables students to gain practical experience of the needs and demands of professional environmental agencies. Students are given a choice of placements in a variety of sectors (such as government, NGOs, private sector). Eligible students who wish to do a work placement in the upcoming summer or fall session must submit an online application form early in the preceding winter term, which can be found on the School''s undergraduate courses webpage along with instructions and the application deadline.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 3.0, "department": "ENV"}]}'::jsonb),
    ('ENV441H1', 'Human Health Impacts of Natural System Alteration', '24S', 'The course introduces students to a wide range of topics and issues about the impacts of change in natural systems (e.g., forests, ocean, climate) on human health. Through readings and discussion, students will explore how the potential health effects of environmental change vary across groups of people having different socio-economic characteristics. A number of case studies or topics will be examined to exemplify why certain populations may be especially vulnerable to different types of environmental changes. Issues related to equity and justice will also be discussed.', null, 4, '{"operator": "OR", "items": ["ENV337H1", "ENV341H1"]}'::jsonb),
    ('ENV450H1', 'Climate Change and Environment Solutions', '12T/24S', 'This is an interdisciplinary course in which students address current climate change problems while incorporating technical, environmental, economic, social, and political concerns.', null, 3, '{"operator": "AND", "items": ["ENV222H1", {"operator": "OR", "items": ["ENV301H1", "ENV350H1"]}]}'::jsonb),
    ('ENV451H1', 'Current Environmental Topics', '24S', 'This capstone course for the School''s core programs will explore current environmental topics, with the goal of integrating the multi- and interdisciplinary strands of each student''s learning to date. This course is for students enrolled in one of the School''s BA programs, or permission of the Undergraduate Associate Director.', null, 3, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV452H1', 'Environmental Science Seminar', '36S', 'Scientists from within and external to the university share and discuss challenges, findings and opportunities. Specific topics (and speakers) vary from year to year but may draw from rehabilitation techniques, contaminants in our environment, environmental health, impacts on landscapes and communities, biodiversity, water, and modelling of environmental processes. This course is for students enrolled in the School of the Environment, Environmental Science Major BSc program, or permission of the Undergraduate Associate Director.', null, 4, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}, {"operator": "OR", "items": ["ENV316H1", "ENV334H1", "ENV337H1"]}]}'::jsonb),
    ('ENV461H1', 'The U of T Campus as a Living Lab of Sustainability', '24L', 'Sustainability is a growing priority for universities all over the world. Many are developing strong operational sustainability goals and targets, and are giving increasing emphasis to teaching and research on sustainability issues. Yet few have committed at the executive level to integrating academic and operational sustainability in the context of treating their campus as a living laboratory of sustainable practice, research and teaching. Arguably, it is such living lab approaches that offer the largest potential for universities to play a significant role in the sustainability transition. This course will explore and apply the living lab concept, in the context of operational sustainability at the University of Toronto. We will begin by looking at the literature on university sustainability and the living lab concept. The bulk of the course will involve undertaking an applied research project on some aspect of campus sustainability, working in close partnership with operational staff at the University of Toronto. Students will develop the skills needed to work across disciplines and fields of study, and with non-academic partners. This course will put students to work on operational sustainability projects identified by the staff working in or with the Sustainability Office at the University of Toronto. Students will be organized into groups, each of which will be assigned one project, to be overseen by one or more U of T staff members. The bulk of the course will consist of regular meetings with the staff "clients", with instructors, and in small groups to undertake a group project. Each group will produce a mid-term and final report, and give a mid-term and final presentation. Each student will also submit two 360 reviews of the group process. A crucial aspect of this course is the ability of students to work collaboratively together in a group environment, and to work effectively with a university staff person acting as a "client" for their work. Students will be provided with a Handbook outlining information on working in groups and the focus of the class in the second week will be on this issue. The first 360 peer review will serve to provide information on how well each group is working. Students are encouraged to discuss and resolve group process issues in the weekly group meetings, and in their regular meetings with the instructor and TA. The second 360 review will occur at the end of the term. The results of the two 360 reviews will be used, where appropriate, to adjust individual marks from the group averages.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV462H1', 'Energy and Environment: Economics, Politics, and Sustainability', '24L/12T', 'This interdisciplinary course examines key ideas in economics, domestic politics and geopolitics that are essential to understanding energy and environmental issues. The course will cover energy markets, how these have fundamentally shaped geopolitical relations and conflicts, and the increasing role that renewable energy and sustainability plays in setting policies.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('ENV463H1', 'Edible Campus', '36L', 'This course situates students and campuses within the context of broader movements for more ecologically rational and socially-just food systems. Topics include critical food systems pedagogy; the political economy of campus food systems; student food (in)security and health; campus food systems alternatives; campus food growing spaces; student/campus-based food movements; campus-community partnerships. The course is praxis-driven and will provide students with opportunities to engage in change-making on their campus, and beyond, through an action-focused project with a campus and/or community partner.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}, {"credits": 10.0, "department": null}]}'::jsonb),
    ('ENV464H1', 'Communicating Climate Change', '24L', 'Climate change is an urgent yet complex problem to communicate. Curiously, many young activists are still using the same messages and images that have been around for decades (i.e., burning globes and apocalyptic scenarios). How did these methods of climate communication emerge? And to what impact in terms of both public perception and policy? In this course, students will examine the historical development of climate communication from its origins in the Cold War to present day. In addition to learning how climate change is discussed and visualized, students will work together to produce creative projects and develop improved communication methods.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('ENV465Y1', 'Toronto Climate Summer School', '24L/12T/36P', 'This is an experiential and interdisciplinary course to learn relevant methods, themes, and topics to engage with climate change in and connected to the Greater Toronto Area (GTA). Guided by place-based pedagogy and environmental justice, experiential learning, and engagement across the physical to social sciences and humanities, this course seeks to equip students with questions, approaches, tools, and community in facing climate change. Students will also gain interdisciplinary research experience by working on faculty supervised projects.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('ENV481H1', 'Special Topics in the Environment', '24S', 'Special topics course designed for advanced Specialist and Major students in School of the Environment programs. This course is for students enrolled in a School Environmental program, or permission of the Undergraduate Associate Director.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "ENV221H1", "ENV222H1"]}'::jsonb),
    ('ENV482H1', 'Special Topics in the Environment', '24S', 'Special topics course designed for advanced Specialist and Major students in School of the Environment programs. This course is restricted to students enrolled in a School Environmental program.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "ENV221H1", "ENV222H1"]}'::jsonb),
    ('ENV491Y1', 'Independent Studies Project', null, 'A research project or selected topic in an area of environment not otherwise available in the Faculty, meant to develop skills in independent study of interdisciplinary topics. This course is restricted to students enrolled in a School of the Environment program. A written proposal co-signed by the student and supervisor must be submitted for approval by the Academic Associate Director of the School normally one month prior to commencing the course. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV492H1', 'Independent Studies Project', null, 'A research project or selected topic in an area of environment not otherwise available in the Faculty, meant to develop skills in independent study of interdisciplinary topics. This course is restricted to students enrolled in a School of the Environment program. A written proposal co-signed by the student and supervisor must be submitted for approval by the Academic Associate Director of the School normally one month prior to commencing the course. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ENV493H1', 'Independent Studies Project', null, 'A research project or selected topic in an area of environment not otherwise available in the Faculty, meant to develop skills in independent study of interdisciplinary topics. This course is restricted to students enrolled in a School of the Environment program. A written proposal co-signed by the student and supervisor must be submitted for approval by the Academic Associate Director of the School normally one month prior to commencing the course. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["ENV221H1", "ENV222H1"]}]}'::jsonb),
    ('ESS103H1', 'Geology in Public Issues', '24L', 'Geologic hazards: earthquakes, volcanoes, landslides, tsunamis. The distribution and politics of natural resources, including petroleum and ore deposits. Nuclear power and nuclear waste disposal. Global change: the geologic record of hot and cold climates, and how the earth survives.  ESS103H1 is primarily intended as a science Distribution Requirement course for Humanities and Social Science.', 'GLG103H1,  ERS103H5', 5, null::jsonb),
    ('ESS104H1', 'Controversies in Earth Science', '24L', 'The evolution of ideas about the origin and development of the earth from the Athenians to the 20th Century, with attention on the age of earth; on the evolution and disappearance of species; on the origin of oceans, continents and mountains; on climate change; and on the courage of scientists in confronting the religious and political views of their time.   ESS104H1 is primarily intended as a science Distribution Requirement course for Humanities and Social Science students. Taught in even years.', 'GLG105H1', 5, null::jsonb),
    ('ESS105H1', 'Our home planet', '24L', 'The nature and evolution of the Earth; plate tectonics; rocks and minerals; volcanism; geological time; fossils; geology of Ontario; environmental issues; and human interactions with the planet.   ESS105H1 is primarily intended as a science Distribution Requirement course for Humanities and Social Science students', 'GLG110H1,  EESA06H3', 5, null::jsonb),
    ('ESS196H1', 'Life and Death in the Solar System', '24L', 'Earth is the only planet in the solar system known to support life. Through directed readings, seminars, videos and lab visits, participants in this course will work with instructors whose own research tackles important questions concerning the origin of life on earth; the limits to life on this planet; implications for life under extreme conditions elsewhere in the solar system; and the life cycles of the planets themselves. The course will involve reading of scientific literature, student-led discussions, oral presentations and research projects, as well as potential field trips to sites in Southern Ontario. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ESS197H1', 'Earth and Life through Time', '24L', 'This seminar will look through the lens of earth history to explore drivers of change in the biosphere and the impacts of these changes. We will focus on episodes of mass extinction, and the spectacular landscape changes and speciation events which often followed. Abrupt or gradual climatic changes, massive volcanism, asteroid impacts, catastrophic carbon releases, and human activity will be evaluated as the causes of major extinction events in Earth history. The course will involve reading of scientific literature, student-led discussions, oral presentations and research projects, as well as potential field trips to sites in Southern Ontario. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ESS198H1', 'Resources and Sustainability', '24L', 'The rise of humanity is intricately linked to the exploitation of natural resources. From its earliest attempts to use fire and extract metals from rocks, to coal-fired steam that brought the industrial revolution, hydrocarbons that fuel international travel and trade, nuclear energy to produce electricity, and the reliance on smartphones in our daily lives, the planet''s resources have brought innovation and problems and require us to ask questions regarding sustainability. This course will explore the gamut from resource extraction and trading, to its societal consequences including global politics, environmental pollution, and remediation. The course will involve reading of scientific literature, student-led discussions, oral presentations and research projects, and potentially field trips to sites in Southern Ontario. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ESS199H1', 'Earth Science Perspectives on Human Origins', '24L', 'Archaeologists and paleontologists depend on earth science to provide the contextual information that is essential to our understanding of human evolution. Among the topics this course will examine are the methods used to determine the age of discoveries, approaches to understanding the environments human ancestors lived in, and how geologists unravel site formation processes. Our discussions will include the role of fire in human evolution, the adaptations of Neanderthals, and the timing of the first appearance of modern humans. The course will be structured around key research localities including Hadar, the Cradle of Humankind, Olduvai Gorge, Wonderwerk Cave, Kebara Cave, Hohlefels, and Pinnacle Point. The course will involve reading of scientific literature, student-led discussions, oral presentations and research projects. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('ESS205H1', 'Confronting Global Change', '24L/8T', 'The emergence of society as a major geological force is considered in terms of the evolving debate about the consequences of human activity for the habitability of our planet. Major issues such as climate change, environmental pollution, and depletion of natural resources are examined.', 'GLG205H1,  ERS321H5,  EEB208H1', 4, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ESS223H1', 'Introduction to Geochemistry', '24L/24T', 'This course introduces students to the basic principles of geochemistry that are used to understand Earth system processes. Topics will include the origin and distribution of elements and isotopes on Earth, mineral compositions, phase diagrams, weathering, and aqueous geochemistry. The course will also cover the thermodynamic and kinetic principles that govern chemical reactions in nature.', 'ENV233H1', 5, '{"operator": "AND", "items": ["MAT135H1", "CHM135H1"]}'::jsonb),
    ('ESS224H1', 'Introduction to Mineralogy and Petrology', '24L/48P', 'An introduction to atomic structure, chemistry, physical properties, and geological significance of rock-forming minerals and rocks. Field techniques and core concepts to identify important minerals and rocks in hand specimens and place them into their geological context. The development of practical skills is emphasized.', null, 5, '{"operator": "OR", "items": ["JEG100H1", "ESS262H1"]}'::jsonb),
    ('ESS234H1', 'Introduction to Geological Field Methods', null, 'A two-week field course in early May or late August. Students are introduced to field geology and to basic field measurement, mapping and documentation techniques (for example in the Espanola - Manitoulin Island area, west of Sudbury). Students are responsible for the cost of board and lodging and transport to and from the field area. Not eligible for CR/NCR option. Note: Enrollment is handled by the department. For registration deadlines, additional fees associated with the field course, course dates, and special registration requirements, please consult the departmental announcements or inquire with ugrad@es.utoronto.ca. Additional fee of up to $918 will apply.', 'ESS330H1,  GLG340H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ESS224H1", "ESS222H1"]}, "ESS241H1", {"operator": "OR", "items": ["ESS262H1", "JEG100H1"]}]}'::jsonb),
    ('ESS241H1', 'Geologic Structures and Maps', '24L/36P', 'Field observations, description and classification of geological structures: stratigraphic and intrusive contacts, unconformities; relative age determination; folds and fold systems; faults and fault systems; boudinage, foliations and lineations; spherical projections and mechanical principles (stress, strain, rheology). Practical work focuses on reading geological maps, constructing cross-sections, and interpreting both in terms of geological processes and histories.', 'GLG345H1,  EESC37H3', 5, null::jsonb),
    ('ESS245H1', 'Computational Geology', '24L/1T/30P', 'A practical introduction to programming. This course will teach an operational knowledge on how to write and execute self written computer programs. Course topics touch upon using a computer without a graphical interface, using an integrated development environment, programming, documenting, debugging, reading and writing data, graphical output, how to navigate existing documentation and internet resources, and last but not least how to effectively ask for help. Students will work individually and in small groups in an inverted classroom setting on earth science related problem sets. Previous programming experience is not required.', 'CSC108H1,  ESS345H1', 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('ESS261H1', 'Earth System Evolution', '24L/36P', 'Interrelationships between Earths atmosphere, hydrosphere, geosphere and biosphere through time; including patterns of evolution and extinction as they are related to changes at the earth''s surface and recorded in the rock record. Laboratories cover major groups of fossils, their classification, use in biostratigraphy, and living analogues. NOTE:  ESS261H1 and  ESS262H1 may be taken in either order; and both are required for advanced courses.', 'GLG217H1', 5, null::jsonb),
    ('ESS262H1', 'Earth System Processes', '24L/24P', 'An introduction to how our planet works, focusing on physical processes that govern the nature and composition of Earth with an emphasis on the dynamic nature of the planet. Topics include surface processes (e.g., weathering and erosion, ocean and atmospheric circulation, weather and climate), crustal processes (e.g., plate tectonics, earthquakes, volcanoes, biogeochemical cycles), and earth-environment interactions (e.g., natural hazards, resource development, and sustainability).', 'JEG100H1', 5, null::jsonb),
    ('ESS299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ESS299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ESS311H1', 'Aqueous Geochemistry', '24L/24P', 'An introduction to aqueous environmental geochemistry emphasising the importance of chemical equilibria, mass transport, and microbiological activity in regulating the chemical composition of natural and contaminated systems.', 'GLG351H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM135H1", "CHM151Y1"]}, "MAT135H1"]}'::jsonb),
    ('ESS312H1', 'Hydrogeology', '24L/24P', 'This course covers groundwater formation, flow and transport, the role of groundwater in geologic processes, and physical, chemical and biological constraints on transport and attenuation of chemicals in groundwater.', 'GLG450H1', 5, null::jsonb),
    ('ESS313H1', 'Contaminants, Environment, Geoethics', '36L', 'One of humanity''s key challenges is growing environmental pollution by a wide range of contaminants entering the environment from anthropogenic activities, including mining (even for critical minerals needed for "green energy"), agriculture, land use change, and industry. Topics covered will include the sources, transport and fate of inorganic and organic contaminants using geochemical, geobiological, and geophysical lenses. Students will investigate the need for mining, remediation and mitigation strategies, and will discuss ethical issues related to activities that lead to contaminant releases and their impact on human and environmental health.', null, 5, '{"operator": "OR", "items": ["JEG100H1", "ESS262H1", "ESS311H1", "JGA305H1"]}'::jsonb),
    ('ESS321H1', 'Mineralogy', '24L/36P', 'Systematic mineralogy (including identification, classification, and description); physical and chemical properties of minerals; crystallography and crystal systems (symmetry, crystal structure, crystal systems); optical techniques in mineral identification.', null, 5, '{"operator": "AND", "items": ["ESS224H1", "ESS234H1"]}'::jsonb),
    ('ESS322H1', 'Igneous Petrology', '24L/36P', 'An overview of the nature and origin of igneous rocks, with particular emphasis on the interpretation of textures and mineral assemblages as they reflect rock-forming processes. Topics include the physical and chemical properties of magma, origin, and evolution of different magmatic series in specific igneous/tectonic environments, geochemical and isotopic characteristics of igneous rocks, and the assimilation, fractionation & crystallization processes.', null, 5, '{"operator": "AND", "items": ["ESS224H1", {"operator": "OR", "items": ["ESS321H1", "ESS221H1"]}]}'::jsonb),
    ('ESS324H1', 'Advanced Geological Field Methods', null, 'A two-week advanced geological mapping project in a challenging field environment. Students learn to compile existing geoscience data, create a geological map and prepare a professional final report on their activities and findings. Not eligible for CR/NCR option. For registration deadlines, additional fees associated with the field course, course dates, and special registration requirements, please consult the departmental announcements or inquire with ugrad@es.utoronto.ca. Additional fee of up to $918 will apply.', 'ESS420H1,  GLG445H1', 5, '{"operator": "AND", "items": ["ESS322H1", {"operator": "OR", "items": ["ESS234H1", "ESS330H1"]}]}'::jsonb),
    ('ESS331H1', 'Sedimentation and Stratigraphy', '24L/36P', 'Formal principles of stratigraphy, types of stratigraphic unit, methods of dating and correlation (biostratigraphic methods, magnetostratigraphy, radiometric dating). Methods of study in surface and subsurface (outcrop measurement, elementary introduction to wireline logs, seismic methods). The principles of facies analysis; sediment transport - sedimentary structures, the flow regime, and sediment gravity flows. The carbonate factory and carbonate rock classification. Trace fossils. Laboratory exercises in understanding facies mapping, isopachs and isolith maps.', 'GLG360H1,  ERS211H5,  ERS313H5', 5, '{"operator": "AND", "items": ["ESS224H1"]}'::jsonb),
    ('ESS362H1', 'Oceanography', '24L/24P', 'An introduction to the physical, geological, chemical, and biological processes governing the world''s oceans. The course emphasizes critical thinking, environmental issues, and interrelationships among scientific disciplines.', null, 5, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('ESS363H1', 'Global Biogeochemical Cycles', '36L', 'Exchange of energy and matter (elements and minerals) between the Earth''s atmosphere, ocean, biosphere, and geosphere. Course-related topics include global biogeochemical cycling of carbon, nitrogen, phosphorous, silicon, iron, and zinc (amongst other elements) and will include both terrestrial and marine ecosystems. Examples and case studies will be viewed from the paleo-, contemporary and potential future global change perspectives.', 'ESS462H1', 5, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["JEG100H1", "ESS223H1", "ESS262H1", "ESS261H1"]}, {"operator": "OR", "items": ["PHY131H1", "PHY132H1", "CHM135H1", "CHM136H1", "MAT135H1", "MAT136H1"]}]}'::jsonb),
    ('ESS381H1', 'Special Topics in Earth Science', '24L/24P', 'A survey of current thinking in Earth science. Topics may include isotope geochemistry, ore genesis, or planetary remote sensing.', null, 5, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('ESS391H1', 'Directed Studies', null, 'An individual study program chosen by the student with the advice, and under the supervision, of a faculty member. Such work may involve obtaining data in the field or lab and analyzing it, an interdisciplinary research project, and supervised readings. Not eligible for CR/NCR option.', 'GLG371H1', null, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('ESS392Y1', 'Directed Studies', null, 'An individual study program chosen by the student with the advice, and under the supervision, of a faculty member. Such work may involve obtaining data in the field or lab and analyzing it, an interdisciplinary research project, and supervised readings. Not eligible for CR/NCR option.', 'GLG372Y1', null, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('ESS398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ESS398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', 'GLG399Y0', null, null::jsonb),
    ('ESS399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ESS410H1', 'Field Techniques in Environmental Geosciences', null, 'A ten-day field course in late summer at the Deep River field site designed to familiarize students in a variety of hydrogeological and biogeochemical field techniques; includes a mixture of lecture, laboratory and field exercises. Not eligible for CR/NCR option. Note: Enrollment is handled by the department. For registration deadlines, additional fees associated with the field course, course dates, and special registration requirements, please consult the departmental announcements or inquire with ugrad@es.utoronto.ca. Additional fee of up to $918 will apply.', 'GLG448H1', 5, '{"operator": "AND", "items": [{"credits": 1.5, "department": null}]}'::jsonb),
    ('ESS423H1', 'Mineral Deposits', '24L/36P', 'This course investigates the geochemistry, geology, and mineralogy of mineral systems. Practical skills that will be developed include identification of ore and gangue minerals in hand and polished sections as well as understanding ore systems from source to the deposit. This will be of interest to students interested in a career in mineral exploration and mining as it will lead to an increased understanding of mineral systems, skills used in mineral exploration, and how to use these to find mineral deposits. Additionally, it will be of interest to students interested environmental science as it will teach identification of ore minerals and associated minerals that are important for assessing and developing remediation techniques for acid mine drainage sites. Finally, it will be of interest to students interested in geochemistry as we will investigate high temperature reactions between fluids and wallrocks.', 'GLG442H1', 5, '{"operator": "OR", "items": ["ESS322H1", "ESS323H1"]}'::jsonb),
    ('ESS424H1', 'Metamorphic Petrology', '24L/36P', 'This course provides a basic understanding of the formative processes of metamorphic rocks through quantitative applications of simple thermodynamic and kinetic principles. Topics include processes of heat and mass transport in orogenic belts, fluid-rock interaction in metasomatic systems, pressure-temperature-time paths of metamorphic rocks, temporospatial patterns of metamorphism through geologic time, and metamorphism in extreme conditions.', 'ESS323H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ESS222H1", "ESS224H1"]}, {"operator": "OR", "items": ["ESS221H1", "ESS321H1"]}]}'::jsonb),
    ('ESS425H1', 'Advanced Methods in the Geosciences', '24L/36P', 'Theory and operation of current analytical techniques applicable to geological and environmental analysis. In each lab, students receive instruction from an experienced analyst and acquire hands-on experience using state-of-the-art analytical equipment. Techniques covered include X-ray Fluorescence, X-ray Diffraction, Electron Probe Microanalysis, Scanning Electron Microscopy, Ion Chromatography, Atomic Absorption spectrometry, Inductively Coupled Plasma Mass Spectrometry, and Raman spectroscopy.', null, 5, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": null}]}'::jsonb),
    ('ESS431H1', 'Basin Analysis', '24L/36P', 'Detailed study of each of the major sedimentary environments. Typical facies assemblages, cyclic sedimentation. Autogenic and allogenic processes. The principles of sequence stratigraphy. The history of the sequence concept; systems tracts and bounding surfaces. Sequence models. What causes sequences: mechanisms of change in base level and accommodation: – tectonism, climate change, eustatic sea-level change.', 'GLG430H1,  ESS332H1', 5, '{"operator": "AND", "items": ["ESS331H1"]}'::jsonb),
    ('ESS441H1', 'Advanced Structural Geology', '24L/24P', 'Principles of geological mechanics: stress, strain, rheology. Faulting, folding and development of tectonic foliations and lineations. Structural analysis of fractures, folds and tectonites.', null, 5, '{"operator": "AND", "items": ["ESS234H1", "ESS241H1"]}'::jsonb),
    ('ESS445H1', 'Global Tectonics', '24L/24P', 'Exploration of physical Earth processes and their relationship to large-scale geological phenomena. Mantle convection as plate tectonic engine; intraplate/plate boundary lithospheric deformation including orogenesis and crustal subsidence. Focus on reconciling geodynamic theory/modelling with geological/geophysical observations.', 'GLG465H1', 5, null::jsonb),
    ('ESS450H1', 'Geophysical Field Techniques', null, 'A ten-day field course in late August at the Deep River field site. Students get hands-on experience using geophysical instrumentation, applying various data collection techniques, and performing data analysis in gravity, magnetic, seismic, electrical, electromagnetic, and radar surveys. Not eligible for CR/NCR option. Note: Enrollment is handled by the department. For registration deadlines, additional fees associated with the field course, course dates, and special registration requirements, please consult the departmental announcements or inquire with ugrad@es.utoronto.ca. Additional fee of up to $918 will apply.', null, 5, null::jsonb),
    ('ESS452H1', 'Electrical and Electromagnetic Imaging', '24L', 'Resistivity, induced polarization, self-potential, and electromagnetic methods are commonly used for mineral exploration and environmental surveys. Students will learn the theory and application of Maxwell''s equations on which these methods are based, and apply this understanding to analysing and interpreting data acquired with these methods. Geophysicists use these methods to image the Earth to depths ranging from several meters to tens of kilometers.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1"]}, "MAT224H1", "PHY250H1", "JGA305H1"]}'::jsonb),
    ('ESS453H1', 'Gravity and Magnetics', '24L', 'Earth''s gravity and magnetic fields provide geophysicists with natural sources to collect data from which they may answer questions related to resource exploration and anthropogenic (archaeology, forensic, environmental) targets. Students will learn about potential theory, data transformation (eg, filtering, upward continuation, analytical signal, reduction-to-the-pole), and apply forward modeling and inversion methods to potential field data.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1"]}, "MAT224H1", "JGA305H1", "PHY254H1"]}'::jsonb),
    ('ESS461H1', 'Palaeoenvironmental Studies', '24L/24P', 'The use of proxy data (terrestrial and aquatic microfossils) to infer past environmental conditions. The nature and extent of Quaternary environmental change is considered in the context of assessing current issues such as acidification, metal pollution, eutrophication and global climate change. Paleoenvironmental techniques are applied in the laboratory.', 'GLG436H1', 4, '{"operator": "AND", "items": ["ESS261H1"]}'::jsonb),
    ('ESS464H1', 'Biological Perspectives on Earth System Evolution', '24L', 'A seminar course focussing on ways that the Earth''s biosphere (terrestrial and marine) has altered the overall functioning of the Earth System over geological time, including (1) influence of terrestrial vegetation on surface processes such as palaeosol development, river geomorphology, erosion, and cycling of major biogeochemical nutrients on land, (2) influence of the marine biosphere on the concentration of O2 and CO2 in the atmosphere, including the origin of the stratospheric ozone layer, and (3) the interactive influence of the terrestrial and marine biosphere on atmospheric moisture transport, production of latent relative to sensible heat fluxes, and the development of the planetary boundary layer. Offered in alternate years.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ESS261H1", "ESS262H1"]}, {"operator": "OR", "items": ["ESS361H1", "ESS362H1", "GGR305H1"]}]}'::jsonb),
    ('ESS465H1', 'Topics in Critical Zone Processes', '24L', 'An in-depth look at a significant aspect of the Earth system. The "critical zone" -- defined as the outer layer reaching from the treetops into the weathered bedrock where rock, water, air and life interact -- is crucial to life and habitats, food production, water quality, and regulating climate. Topics will vary depending on instructor expertise, who may focus on biosphere-atmosphere interactions, or microbiologically driven cycling of energy and matter in the subsurface. Emphasis will be placed on approaches to quantitatively model interactions and reading of primary scientific literature.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ESS363H1", "ESS362H1"]}, {"credits": 9.5, "department": null}]}'::jsonb),
    ('ESS481H1', 'Advanced Topics in Earth Sciences', '24L/24P', 'This course is offered on an irregular basis, typically in the winter term. Students are advised to consult the departmental notices with respect to course times and content, but should expect an in-depth study of modern earth science questions, for example mineralogy and material science, advanced petrology, or exploration geochemistry. Course instructors will often, but not always, be recruited from Industry.', null, 5, null::jsonb),
    ('ESS490H1', 'Geological Capstone Fieldtrip', null, 'The capstone course is an opportunity to integrate your collected knowledge of geology, geophysics, and environmental geoscience in an exciting and varied field setting. You will use information gathered across a variety of field sites to examine how Earth processes have shaped the larger Earth system, and how this has influenced humans. Most past trips were run for two weeks during the summer months and explored Scotland, Hawaii, Newfoundland, Labrador, or the southwestern USA; future sites and dates will vary depending on instructor and destination. Note: Enrollment is handled by the department. For registration deadlines, additional fees associated with the field course, course dates, and special registration requirements, please consult the departmental announcements or inquire with ugrad@es.utoronto.ca. Additional fee of up to $988 may apply.', 'GLG420H1', 5, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}]}'::jsonb),
    ('ESS491H1', 'Undergraduate Thesis Project', null, 'Research emphasising methods used in field and experimental work. Students must obtain the consent of an instructor and register with the undergraduate coordinator and are urged to do so toward the end of their third year. In addition to submitting a thesis, students are required to give an oral presentation of their research results to an open meeting of the department. Not eligible for CR/NCR option.', 'GLG471H1', 5, null::jsonb),
    ('ESS492Y1', 'Undergraduate Thesis Project', null, 'Research emphasising methods used in field and experimental work. Students must obtain the consent of an instructor and register with the undergraduate coordinator and are urged to do so toward the end of their third year. In addition to submitting a thesis, students are required to give an oral presentation of their research results to an open meeting of the department. Not eligible for CR/NCR option.', 'GLG470Y1', 5, null::jsonb),
    ('EST100H1', 'Elementary Estonian Language and Culture I', '48P', 'Learn essential Estonian vocabulary, basic grammar and develop elementary conversational competence. Popular songs, poetry, and structured dialogue are among the various tools for achieving these objectives. Students will learn commonly used phrases and expressions used in everyday situations, from greeting people to making purchases in stores, and ordering meals in cafes. The course is designed for students with either no fluency or minimum fluency in Estonian.', 'EST100Y1', 1, null::jsonb),
    ('EST101H1', 'Elementary Estonian Language and Culture II', '48L', 'This course expands the student''s command of Estonian from the introductory level. The course will consist of themed sessions using language for travel in Estonia, savouring the language of Estonian cuisine, and the lyrics of popular, folk and classical Estonian music. These themed sessions will also enable students to better understand the proper inflections of nouns and tenses of verbs in both dialogue and written exercises. This course is open to students with minimum fluency in Estonian.', 'EST100Y1', 1, '{"operator": "AND", "items": ["EST100H1"]}'::jsonb),
    ('EST200H1', 'Intermediate Estonian Language and Culture I', '48P', 'This course develops the student''s language skills via an exploration of Estonian culture - including its music, literature, film and media. Each of these areas will be examined through readings, writing about one''s impressions, and speaking about them to others in the class. The course consists of a combination of both classroom and web-based learning. The course is open to students with some fluency in Estonian.', 'EST200Y1', 1, '{"operator": "AND", "items": ["EST100H1", "EST101H1"]}'::jsonb),
    ('EST201H1', 'Intermediate Estonian Language and Culture II', '48P', 'Through an exploration of Estonian culture both in Estonia and the diaspora, students will further develop their skills in speaking, reading and writing in Estonian. Students will learn about the main characteristics of Estonian society – its history, way of life, the Estonian economy and business environment, and Estonian current affairs. Students will discuss recent trends and challenges in the development of Estonian society. The course will combine both classroom and web-based learning. It is open to students with elementary fluency in Estonian, both spoken and written.', 'EST200Y1', 1, '{"operator": "AND", "items": ["EST100H1", "EST101H1"]}'::jsonb),
    ('EST202H1', 'Estonian Culture in the 21st Century', '24L', 'The course provides an introduction to Estonian contemporary culture: literature, theatre, music, arts and architecture, environmental issues, minorities, regional dialects, and, last but not least, politics. The course is taught in English, all reading materials are in English.', null, 1, null::jsonb),
    ('EST204H1', 'Introduction to Estonian Culture', '24L', 'This course provides an introduction to Estonian culture: Folklore and folk traditions, visual arts and architecture, and contemporary popular culture and media.', null, 1, null::jsonb),
    ('EST205H1', 'Estonian Cinema', '24L', 'This course provides an introduction to Estonian cinema: feature films, documentaries, and animation films.', null, 1, null::jsonb),
    ('EST206H1', 'Environmental Humanities in Central and Eastern Europe', '24L', 'The course gives an overview of the ongoing research in European environmental humanities, with an emphasis on ecocriticism and environmental history in Central and Eastern Europe - organizations, institutions, publications, online resources, current topics, theories and methodologies. Taught in English, all materials in English.', null, 3, null::jsonb),
    ('EST207H1', 'Indigenous Cultures of Northern Eurasia', '24L', 'The course focuses on the history and current status of various indigenous groups that live in the vicinity of the Polar Circle across Eurasia. Geography of indigenous peoples of Northern Eurasia. Livelihood and environmental conflicts. Colonial gaze, mechanisms of repression and deprivation, and indigenous resistance. Minority language p[olitics. Indigenous songs and stories. Current situation and awareness-building. Taught in English, all materials in English.', null, 3, null::jsonb),
    ('EST300H1', 'Estonian Language through Contemporary Media', '36P', 'Advanced Estonian language course focusing on media and communication. We will read and discuss the main national news channels - Aktuaalne Kaamera, Eesti Päevaleht, Vikerraadio Uudis +, as well as read the Estonian cultural weekly Sirp and observe the monthly newspaper Müurileht to get a grip of Estonian youth culture. Public speeches by the Estonian President, as well as scholars and scientists will be discussed.', 'EST300Y1', 1, '{"operator": "AND", "items": ["EST201H1"]}'::jsonb),
    ('EST300Y1', 'Advanced Estonian', '72P', 'Advanced grammar and stylistics through study of a variety of texts; problems of composition; translation; oral and written practice. (Offered in alternate years)', null, 1, '{"operator": "AND", "items": ["EST200Y1"]}'::jsonb),
    ('EST420Y1', 'Independent Study', null, 'A year-long reading and research project of significant depth in a major topic in Estonian language, literature or culture approved and supervised by an instructor. Not eligible for CR/NCR option.', null, null, '{"operator": "OR", "items": ["EST300Y1", "EST400Y1"]}'::jsonb),
    ('EST421H1', 'Independent Study', null, 'A semester-long reading and research project of significant depth in a major topic in Estonian language, literature or culture approved and supervised by an instructor. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ETH201H1', 'Contemporary Moral Problems', '24L', 'ETH201 is an introductory course in ethics. How should we live? Which course of action is the right one? When and why should we blame ourselves and/or others? We all have and exercise moral opinions; this course is about justifying them. The course begins with some critical reasoning skills, and then explores philosophical strategies for justifying moral beliefs. We will then examine some specific issues of moral and political significance before concluding with psychological mechanisms behind moral attitudes and behaviour.', null, 2, null::jsonb),
    ('ETH210H1', 'Rationality and Action', '36L', 'An introductory survey of attempts that have been made to develop a formal model of practical rationality, with particular emphasis on the way moral considerations enter into those deliberations. Topics may include: utility-maximization theory, introductory game theory, consequentialism, and deontic reasoning, as well as the limitations of rationality.', null, 2, null::jsonb),
    ('ETH220H1', 'Moral Psychology', '36L', 'A study of issues that arise at the intersection of psychology and moral philosophy. Why do people act morally? What role do reason and emotion play? Can we know what is right, yet not be motivated to do it? What role can science play in advancing our understanding of morality?', null, 2, null::jsonb),
    ('ETH230H1', 'Morality in Cross-Cultural Perspective', '24L', 'Is morality universal, or does it vary by time and place? This course will examine cultural differences in moral codes from both empirical and philosophical perspectives.', null, 2, null::jsonb),
    ('ETH350H1', 'Topics in Value Theory', '24L', 'Selected topics in value theory, broadly construed (ethics, political theory, law). Consult the Centre for Ethics website for offering information.', null, 2, null::jsonb),
    ('ETH401H1', 'Seminar in Ethics', '16L/16S', 'The seminar will expose advanced undergraduates to cutting edge research in ethics. It meets bi-weekly over the entire academic year. Participants will attend research presentations at the Centre for Ethics (topics have included bioethics, indigenous rights, equality and education, free speech, and workplace democracy). They will also meet individually with the instructor to plan an independent research project related to the theme of the course. In the winter term, students will present their research and discuss it with the other students in the seminar. (Note that this is an "H1Y" course -- a half-credit course taught throughout both Fall and Winter terms.)', null, 2, '{"operator": "OR", "items": ["PHL365H1", "PHL375H1", "PHL271H1", "POL200Y1", "POL330Y1"]}'::jsonb),
    ('EUR200Y1', 'Europe: Nation-State to Supranational Union', '48L/24T', 'An analysis of the development of European political regimes from 1789 until the 2004 and 2007 enlargements of the European Union to include the countries of the former Soviet bloc. This course identifies the decisive forces and factors affecting the operation of constitutions and institutions within the countries which came to form the European Union: nationalism, multi-nationalism, internationalism and supranationalism.', 'HIS241H1/ HIS242H1', 3, null::jsonb),
    ('EUR299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EUR299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities… . Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EUR300H1', 'Special Topics in European Affairs', '24L', 'This course offers students the opportunity to explore key issues in European Affairs. Topics vary from year to year, depending on the instructor. See Department website for current offerings. Course may not be repeated under the same subtitle.', null, 3, '{"operator": "AND", "items": ["EUR200Y1", {"credits": 4.0, "department": null}]}'::jsonb),
    ('EUR301H1', 'Modernity and Its Discontents', '24L', 'This European intellectual history course introduces students to the temporal rupture called modernity—beginning with what Max Weber calls “disenchantment” and moving through the death of God—and ultimately the resignation from attempts to find a viable replacement for God. Topics include Marxism-Leninism, psychoanalysis, expressionism, structuralism, phenomenology, existentialism, anti-politics, and deconstruction. Authors include Nietzsche, Lenin, Kafka, Freud, Husserl, de Beauvoir, Heidegger, Arendt, Adorno, Sartre, Girard, Foucault, Derrida and Havel.', null, 2, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('EUR398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EUR398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EUR399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EUR399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities… . Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EUR400H1', 'Selected Topics in European Affairs', '24L', 'This course offers upper year students the opportunity for an in-depth examination of various themes in European Affairs. Topics vary from year to year, depending on the instructor. Course may not be repeated under the same subtitle. May include an International Course Module or visiting Professor.', null, 3, null::jsonb),
    ('EUR401H1', 'Selected Topics in European Affairs', '24L', 'This course offers upper year students the opportunity for an in-depth examination of various themes in European Affairs. Topics vary from year to year, depending on the instructor. Course may not be repeated under the same subtitle. May include an International Course Module or visiting Professor.', null, 3, null::jsonb),
    ('EUR495H1', 'Independent Studies', '2P', 'An in-depth of an issue of relevance to the European Union. Content depends on the instructor. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('EUR498H1', 'Special Topics in European Affairs: European Union', '24L', 'What is the European Union? Which are its core institutions and how do they work? What is the scope of its directives and programs, and how do they fit in with the member-states'' policies? What is the role of the EU as an international actor? This course on Special Topics in European Affairs aims at answering all these questions. The course will start with an introduction to integration in Europe, the development of the EU, and some theories and approaches to its study. It will then review the main political, economic, and judiciary institutions in the EU. Last, it will examine some important policy areas and challenges at the European level, including migration and asylum, social cohesion, counterterrorist initiatives, scenarios after Brexit, relations between the EU and its neighbours, and foreign policy. Special care will be given to explaining the political interaction between the EU institutions and the member-states, on the one hand, and the EU''s Directives and policy frameworks and the members'' policies, on the other hand.', null, 3, '{"operator": "AND", "items": [{"credits": 12.0, "department": null}, "EUR200Y1", {"operator": "OR", "items": ["POL207Y1", "POL359Y1", "POL359H1"]}]}'::jsonb),
    ('FAH101H1', 'Monuments of Art History', '20L/10T', 'An introduction to the arts and architecture from antiquity to the present day which emphasizes the deep connection between art and history. This broad overview will examine carefully a selection of works, including real objects and buildings in Toronto, which are representative of the upper-level courses currently offered by the Art History faculty. Special attention is paid to developing essential art historical skills, including the ability to look at, analyze, and write about works of art and architecture. Tutorials provide training in and experience applying the basic principles and vocabulary employed in art-historical scholarship. Frequent short writing assignments and exercises will be based on readings, lectures, and museum or gallery visits to collections in Toronto. No previous knowledge of history of art or architecture is required.', 'FAH101H5', 1, null::jsonb),
    ('FAH102H1', 'Art and Ideas', '24L/6T', 'A survey of the history of art, architecture and allied arts. This introduction to the history of art will examine a wide range of objects, selected and discussed in connection with a special theme to be selected by the instructor. Students will be expected to study the history and significance of art through the close reading of selected texts that relate to both art and theory. Special attention will be given to developing essential art historical skills necessary for upper level courses. The topic for each semester will vary based on the instructor. No previous knowledge of history of art or architecture is required. Frequent writing assignments and exercises will be based on readings, lectures, and museum or gallery visits to collections in Toronto.', 'FAH101H5', 1, null::jsonb),
    ('FAH194H1', 'Public Art: Local and Global', '24S', 'We are surrounded by public art, whether in the form of official commemorative monuments or ephemeral (some say illegal) street art. We will examine the history and current practice of this important art form in Toronto and by comparison, globally. The focus will be on discussing the nature, roles, and issues pertaining to contemporary public art that we can see in situ in downtown Toronto. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FAH195H1', 'On Foot: From Pilgrimage to the Mobile City', '24S', 'Walking is a basic human activity, yet it also defines and shapes us. In order to understand the permutations of this seemingly simple activity we will look at walking in a variety of contexts through the study of texts, art, movies and the built environment. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FAH196H1', 'Marco Polo''s World', '24S', 'This course explores the visual and material worlds of the Italian traveller Marco Polo, which are described in his Travels. Together we will read sections of this text and explore their meaning with respect to the objects and monuments of Marco Polo''s time from the regions to which he travelled. By studying cartography, art, architecture, and urban form in the expansive medieval world of Marco Polo, the course will introduce us to the global world of the Middle Ages. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FAH197H1', 'Classical Art from Greek Gods to Roman Gladiators', '24S', 'The ancient Greeks and Romans lived in a world full of images. Ancient visual culture comprises not only the high arts but also the everyday. This course is meant to introduce students to key ideas about how art and images in general impacted the life of ancient Greeks and Romans. Students will learn to examine various categories of visual material ranging from the pictorial and applied arts (painting, sculpture, architecture) to everyday artifacts (for example, domestic wares, jewelry or weapons). Through a series of discussion-centred seminar sessions students will explore the interconnections between art and ideology, art and identity as well as visuality and viewing. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FAH198H1', 'Shocking Artists, Shocking Art', '24S', 'Art causes scandals for many reasons, provoking a range of consequences, including censorship, cuts to government funding of the arts or even destruction of the work in question. In this course we will consider a number of kinds of art scandal arising from exhibition in public galleries and urban spaces, including those that have to do with legal issues such as plagiarism and vandalism; aesthetic objections on the part of the public, ranging from perceived obscenity to simple resentment of abstract art; racism; sacrilege; and political subversion, amongst others. We will consider the work of artists including Chris Ofili, Joep van Lieshout, Paul McCarthy, Damien Hirst, Michael Snow, Sally Mann, Banksy, Rachel Whiteread, Richard Prince, Andres Serrano, Robert Mapplethorpe, Carl Andre, Maya Lin, and Jeff Koons, amongst others. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FAH199H1', 'Architecture of Toronto', '24S', 'The architecture of Toronto is characterized by artful and influential monuments as well as stylistically incoherent neighbourhoods, vibrant civic spaces alongside dysfunctional infrastructure. This course investigates how Canada''s national metropolis came to embody such extremes of architectural richness and urban contradictions. The seminar focuses on how to "read" the buildings of Toronto and think critically about the forces that have shaped city planning, monuments, public space, and concepts of heritage. Readings and discussions will be combined with field trips, research on site or in the archives, and direct engagement with local communities and preservation initiatives. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FAH205H1', 'Clay: A Material and Visual History', '24L', 'This course will reveal the deep history of clay, stretching back to the Palaeolithic period with the first clay figurines; through the Neolithic period with its extensive use of clay for the earliest permanent houses, the first inorganic containers, and many votive offerings in clay; all the way to the present day with the ceramic art of Pablo Picasso, Grayson Perry, and Ai Weiwei. Our approach will also be thoroughly global, ranging from the Maya of Mesoamerica to the Mingei of Japan. The course will involve hands-on elements too, particularly with the nearby Gardiner Museum of Ceramic Art.', null, 1, null::jsonb),
    ('FAH206H1', 'Prehistoric Aegean and East Mediterranean Art and Archaeology', '24L', 'An overview of the major monuments, artifacts, themes and problems in the study of the archaeology, art and architecture of the Aegean region and the east Mediterranean to 1000BC.', null, 1, null::jsonb),
    ('FAH207H1', 'Greek and Roman Art and Archaeology', '24L', 'An overview of the major monuments, artifacts, themes and problems in the study of the archaeology, art and architecture of the civilizations of Greece and Rome.', null, 1, null::jsonb),
    ('FAH208H1', 'Heroes of the Classical World', '24L', 'This course is an introductory level study of Greek and Roman Art, explored through the concept of the hero. The course surveys the representations of mythological heroes a well as historical individuals who comply with the notion of hero in Greek and Roman cultures (warriors, athletes, political leaders, etc.). Examining their religious, civic and political contexts allows students to learn how visual culture deals more broadly with larger issues within the respective ancient societies. Readings are drawn from an array of primary and secondary sources both art historical and literary, and the visual exploration of certain mythological narratives teaches how stories are conveyed in the art of Greece and Rome. Basic issues of style and art historical development of the period are also addressed, as are various theories regarding the notion of the hero. This course provides ample opportunity to reflect upon ancient heroes'' contemporary relevance, through various assignments and group projects.', null, 1, null::jsonb),
    ('FAH215H1', 'Early Medieval Art and Architecture', '24L', 'An overview of major monuments and themes in the art and architecture of Western Europe and the Byzantine East from the third until the eleventh century.', 'FAH215H5/ VPHB53H3', 1, null::jsonb),
    ('FAH216H1', 'Later Medieval Art and Architecture', '24L', 'An overview of major monuments and themes in the art and architecture of Western Europe and the Byzantine East from the eleventh until the fifteenth century.', 'FAH216H5/ VPHB53H3', 1, null::jsonb),
    ('FAH230H1', 'Renaissance Art and Architecture', '24L', 'A selective survey of the major art centres and types of artistic and architectural production in Italy and northern Europe, from the early fifteenth century to the mid-sixteenth. Themes include the relations--artistic, economic and ideological--between northern and southern Europe during this period, the changing role of art in religious life, the emergence of secular themes, and the legacies left by Renaissance art to modern life and culture.', 'FAH274H5', 1, null::jsonb),
    ('FAH231H1', 'Baroque Art and Architecture', '24L', 'Major forms of expression in the visual arts ca. 1600 - ca. 1750 with particular attention to forms, techniques, theories, and patronage of the arts as well as biographies of artists in Italy, France, the Netherlands, Flanders, Germany and England.', 'FAH279H5/ VPHB64H3', 1, null::jsonb),
    ('FAH245H1', 'Modernism and anti-Modernism, c. 1750-1900', '24L', 'An introduction to the advent and development of art movements including Rococo and Neoclassicism; Romanticism and Revolution, Realism and the advent of Photography, Impressionism; Academic art; Post-Impressionism.', 'FAH287H5/ VPHB58H3', 1, null::jsonb),
    ('FAH246H1', 'Art Since 1900', '24L', 'An introduction to the consolidation of Modernist tendencies in Europe to the mid 20th century and to the many contemporary responses to these achievements. Individual artists, including Picasso, Matisse, Duchamp, and Matthew Barney are considered in their relationship to various art movements and the theories that supported them, including Expressionism; Abstraction and Constructivism; Dada and Surrealism; Neue Sachlichkeit; Abstract Expressionism; Pop; Conceptual Art; Earth Art; Feminist Art; Postmodernism; New Media Art.', 'FAH288H5/  FAH289H5/  VPHB58H3', 1, null::jsonb),
    ('FAH248H1', 'Canadian Painting 1665-1960', '24L', 'An introductory survey of the history of painting in Canada from the 17th to the 20th century.', 'FAH292H5', 1, null::jsonb),
    ('FAH251H1', 'Black Art in North America', '24L', 'This introductory course will survey the interrelated history of Blackness and artistic production in the United States, Mexico, the Caribbean, and Canada. Starting in the eighteenth century with the advent of the transatlantic slave trade and covering up to Black Lives Matter movement, the course proceeds chronologically and considers the Black Art within its larger social context. By discussing the aesthetic qualities of artworks and the careers of Black artists alongside of the history of anti-Black racism in North America, we will explore both how the visual has been used as a tool of domination and how art can challenge or subvert racist ideologies. At the end of the course, students will be familiar with the primary figures, debates, and works of art that constitute the field. They will also be comfortable discussing the history anti-Black racism and its current manifestations. Topics include: the visual culture of slavery and abolition, hemispheric and transatlantic modernisms, the racial politics of "outsider" and "folk" art, the Black Arts Movement, and art and mass incarceration.', 'FAH351H1, and  FAH280H1 (Special Topics in Art History: Black Art in North America) offered in Fall 2022.', 1, null::jsonb),
    ('FAH252H1', 'Introduction to the History of Photography', '24L', 'This course surveys the history of photography in Europe and North America, from its origins to recent innovations in digital imaging. Emphasis is placed on the various aesthetic, scientific, and political discourses in which photography has been located, and the assumptions and premises associated with the medium''s relationship to reality.', 'FAH291H5/ FAH352H1', 1, null::jsonb),
    ('FAH255H1', 'Art of Indigenous North America', '24L', 'A broad survey of Indigenous arts in North America from Mexico to the Arctic, and from ancient to modern. Students will gain a basic literacy in key artforms including painting, architecture, basketry and more, grounded in an awareness of Indigenous realities and historical currents.', 'FAH275H5', 1, null::jsonb),
    ('FAH256H1', 'Arts of Indigenous North America: East and North', '24L', 'A broad survey of Indigenous arts in North America focusing on the east and the north, from ancient Mississippian cities, to historic Anishinaabe and Haudenosaunee cultural traditions, to Inuit modern and contemporary art. Topics from resource extraction and water politics to ancestral arts and modern markets will emerge throughout, all departing from analysis of art objects in their cultural context. Assignments draw on the rich variety of Indigenous arts in local Toronto institutions and public spaces.', 'FAH255H1', 1, null::jsonb),
    ('FAH257H1', 'Arts of Indigenous North America: South and West', '24L', 'A broad survey of Indigenous arts in North America focusing on the south and the west, from Mesoamerican monuments, to Northwest Coast chiefly arts, to contemporary clay in the Southwest. Topics from resource extraction and water politics to ancestral arts and modern markets will emerge throughout, all departing from analysis of art objects in their cultural context. Assignments draw on the rich variety of Indigenous arts in local Toronto institutions and public spaces.', 'FAH255H1', 1, null::jsonb),
    ('FAH260H1', 'The Artistic Landscape of East Asia', '24L', 'An overview of major monuments and themes in the art and architecture of East Asia (China, Japan, Korea, Vietnam, Mongolia and Tibet), from the Neolithic to the present.', 'VPHB73H3', 1, null::jsonb),
    ('FAH262H1', 'Art and Visual Experience in Modern and Contemporary East Asia', '24L', 'An overview of major monuments and themes in the art and architecture of East Asia (China, Japan, Korea, Vietnam, Mongolia and Tibet) and its diaspora in the nineteenth and twentieth centuries.', 'VPHB77H3', 1, null::jsonb),
    ('FAH265H1', 'Monuments of the Islamic World', '24L', 'This course explores the architecture of the Islamic world from the 7th - 12th centuries through the lens of its major monuments throughout the central Islamic lands, North Africa and Spain. Through an emphasis upon the Umayyad, Abbasid, Fatimid and Seljuk periods, the course explores the range of cultural, political, social and religious aspects related to the development of the built environment. It also considers the impact of Islam''s encounter with late antiquity and aims to position the rise of Islamic architecture within the context of this encounter. Additionally, the architecture is contextualized through a study of the urban history of select early and medieval Islamic cities.', null, 1, null::jsonb),
    ('FAH270H1', 'Architecture: Rituals and Monuments', '24L', 'A survey of architecture from pre-history to the start of modernism, with attention given to the ways in which architecture shapes human experience.', null, 1, null::jsonb),
    ('FAH272H1', 'Modern Architecture from 1750 to the Present', '24L', 'An introduction to the buildings, issues and ideas from Neoclassicism to the present.', null, 1, null::jsonb),
    ('FAH273H1', 'Canada Buildings and Landscapes', '24L', 'An introduction to the traditions and patterns of building in Canada taking into account the unique landscapes, resources and history that comprise what is now a unified political entity. Lectures will pay special attention to the complexity of architecture throughout Canada including issues of land rights, natural resources, immigration, settlements and urban design, transportation, and heritage issues. A special feature of this class will be the opportunity to study Toronto first-hand through class projects. No previous architectural history study is required.', null, 1, null::jsonb),
    ('FAH280H1', 'Special Topics in Art History', '24L', 'The thematic study of various aesthetic, cultural, social, political, and theoretical aspects of global art and photography.', null, 1, null::jsonb),
    ('FAH299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FAH299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FAH303H1', 'Emergence of Greek Civilisation', '24L', 'This course investigates the material culture, art and architecture of the Aegean civilizations from the Neolithic through to the building of the palaces of Crete around 2000BC.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH304H1', 'Architecture of Ancient Greece', '24L', 'In this course we will survey the history of Greek architecture and its impact on the buildings of the ancient Mediterranean. Chronologically, we will begin in the latter second millennium BCE, examining the consequences of the collapse of Mycenaean society on Greek building, after which we will examine the synthesis and dissemination of exciting new forms of monumental building at Greek sanctuaries and cities during the Archaic and Classical periods (ca. 700–350/323 BCE). We will conclude with the developments of the Hellenistic period, the era of eastern Mediterranean empires when architectural patronage is increasingly dominated by Greek and Hellenized royalty. Along the way, the course will examine topics such as the interpretation of meaning in Greek buildings and their sculptural decoration, the origins of building technologies, the interaction of Greek and non-Greek architects and builders, and the reception of Greek architectural forms within non-Greek contexts throughout the Mediterranean.', 'FAH380H1 (offered as "Greek Architecture") taken in Winter 2020 and 2022', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "FAH"}, "CLA210H1", "CLA220H5"]}'::jsonb),
    ('FAH307H1', 'Ancient Art, Migration, and the Barbarian ''Other''', '24L', 'This course surveys the cultural, artistic and social interactions between the Graeco-Roman world and the so-called ''Barbarians'' beyond its eastern and northern confines. Chronologically, it spans from the Greek Geometric and Archaic periods (9th - 6th c. BCE) to the disintegration of the Western Roman Empire and the emergence of Early Medieval Europe (6th- 7th c. CE). The course will address issues of artistic production, material culture, ritual and cult in relation to the mobility of peoples and groups, objects and individuals.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH308H1', 'City of Athens: Art, Politics and Society', '24L', 'This course provides a detailed investigation of the city of Athens, focusing on the art, architecture and archaeology in the later Archaic and Classical Period. A combination of topographical and chronological approach is taken to familiarize the students with both the physical cityscape as well as its development in the context of major areas of interest, such as politics, religion and social customs. Some broad themes explored include: art, democracy and propaganda (Agora), the impact of the Persian wars, ritual and religious festivals (Acropolis), the symposium, Athenian women, funerary art (Kerameikos), cult, sanctuaries and votives, art and Athenian drama. The course will also feature digital humanities components in the assignments, which may involve spatial mapping, 3D tools/VR and/or databases, as well as a trip to the Royal Ontario Museum.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH309H1', 'City of Rome', '24L', 'The art, architecture and archaeology of the city of Rome to AD476.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH310H1', 'Greek Vase Painting', '24L', 'This course is a comprehensive exploration of the art of Greek vase painting, covering material from the late Geometric period (8th C. BCE) to the late Classical Period (4th C. BCE). While iconography and narrative will form a major portion of the content, the class will also explore issues surrounding material and technique, the prevalent sympotic (drinking) culture and Greek rituals that provides the cultural framework, dynamics of trade, theories of viewership and semiotics, status of the artist, and other historiographical concerns, including problematic issues surrounding the modern practice of collecting.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH311H1', 'Greek Sculpture', '24L', 'The course provides a thorough examination of ancient Greek sculpture from 7th - 1st century BCE, which in many ways defined the canon of western art that was to follow. Classic issues of style, dating, and technique are complemented by putting them into the contexts of cultural history, religion and socio-politics. While the course is a traditional monument-based survey of major sculptural works from the ancient Greek world, several important issues are also addressed, pertaining both to contemporary society and the study of other areas of art history. These include but are not limited to: gender, social class, colonialism, notion of the artist, originality, and aesthetic theory.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH312H1', 'Art of the Hellenistic Age', '24L', 'Transformation in the visual arts, paintings, sculpture, and mosaics of the expanding Greek world c. 400BC to c. 100BC; the response to Hellenization from the new artistic centres of Asia Minor and Italy.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH313H1', 'Greek Myth in Ancient Art', '24L', 'A general introduction to Greek mythology and its uses (and abuses) by the Greeks and Romans through the art of antiquity. Students will learn about gods and goddesses, heroes and heroines, their attributes and stories which constituted the subjects of (not only) ancient art.', 'CLA204H1', 1, null::jsonb),
    ('FAH314H1', 'Eroticism in Ancient Art', '24L', 'Erotic ''imagery'' – sculptures, reliefs, paintings – is ubiquitous in ancient art, to a degree that modern viewers have often found disturbing. This course faces the challenge posed by the ancient predilection for such imagery and explores it from a critical and scholarly perspective. At its most basic level, it reassigns a seemingly universal segment of human ''nature'' and experience to the realm of culture, by examining the imagery against the background of ancient constructions of sexuality, gender and the body. But it also explores the libidinal and hedonic structure of the works of art themselves and asks for the functions of erotic imagery in its respective contexts. The course will avail itself of the excellent research on gender, sexuality and eroticism in antiquity that has been produced over the past few decades, and it will also explore the topic''s lateral connections with the thematic fields of ancient humour, the ''grotesque'', apotropaism, myth and magic.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH318H1', 'Monastic Art and Architecture', '24L', 'An examination of the role played by monks and nuns in the creation and use of art and architecture in the Middle Ages.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH319H1', 'Illuminated Manuscripts', '24L', 'A focused survey of different types of manuscripts and their images from the origins of the book in Late Antiquity to the invention of printing.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH325H1', 'Urban Islam', '24L', 'By challenging essentialist questioning of Islamic urbanism, this course considers the inter-animated and complex web of forces that drive cities forward by identifying repertoires of underlying logic. Through a deep and historically situated reading of Medieval Mecca, Medina, Damascus, Jerusalem, Baghdad, Cairo, and Cordoba, we will map and encode history on the urban scale to reveal what makes a city "Islamic." Visual mapping skill cultivation for communication purposes (both digital and analogue) will be taught throughout to enhance understandings of urban complexity in rich historical contexts.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH326H1', 'Cultural History of Islamic Spain', '24L', 'From its earliest beginnings as an Umayyad province and up until the 15th century, al-Andalus acted as a lynch pin within the Mediterranean world. Connecting the Islamic empire in the East and forging links of trade and cultural exchange with Europe to the West, cities such as Cordoba and Granada captured the imagination of contemporary chroniclers, earning descriptions in the sources as truly “first-rate places”. Through an exploration of the historical, artistic, architectural, urban, social and economic contexts, this course will engage with and expand upon current understandings of this seminal period in Islamic history to examine Islam''s encounters and modes of cultural exchange with Europe and the Mediterranean world.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH327H1', 'Secular Art and Architecture of the Middle Ages', '24L', 'A consideration of art and architecture made for the court, the aristocracy, and other patrons outside the realm of the Christian church.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH328H1', 'Gothic Cathedral', '24L', 'An examination of the Gothic cathedral from its origins in Paris in the 1130''s through its development and elaboration in France, England and Italy. This course also considers monumental decorations in painted glass, wall painting, tapestry and portal sculpture.', 'FAH351H5', 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH330H1', 'German Art and Architecture in the Age of Dürer', '24L', 'Albrecht Dürer and the painting and printmaking of his contemporaries. Consideration of the great Hall churches of Saxony and the altarpieces of Tilman Riemenschneider and his contemporaries; the status of the arts and attitudes towards Italian art, and the consequences of the Reformation for religious imagery.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH331H1', 'Netherlandish Renaissance Art and Culture', '24L', 'The Netherlands had become one of Europe''s most fertile artistic cultures by the sixteenth century. Hieronymus Bosch and Pieter Bruegel are famous today for their paintings of Hell and peasant life. Other painters introduced mythological and erotic subject matter, while practitioners in the other arts were perhaps even more widely known. Netherlandish sculptors created the tombs of northern European rulers, defining their public identity in the communal space of church and chapel. Miniature carved altarpieces helped guide modes of private devotion and were widely imitated from Italy to Scandinavia. Netherlandish tapestries broadcast the heroic deeds of the Caesars and the patriarchs in the palaces of kings and high nobles as prototypes for their reigns. We will examine the rise of the Renaissance manner in northern Europe, the role of the religious arts, the ideology of urban culture, the consequences of the Reformation and iconoclasm, the functions of various species of portraiture, and the particular properties of different media, while dedicating much attention to Bosch and Bruegel. And we will concentrate on the sixteenth century, the era in which the Netherlands was closely linked to the rest of Europe, from Italy to Sweden, from England to Ukraine.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH335H1', 'The Art of Love in the Renaissance', '24L', 'Love is studied not only as a favorite theme of Renaissance art, but as the basis of some of its fundamental aesthetic claims. The question of love connects Renaissance art to important strains of philosophical thought and religious spirituality, as well as to some urgent realities of social life.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH337H1', 'Rivalry, Imitation and Envy in Italian Renaissance Art', '24L', 'This course examines works in different art media, including painting, sculpture and prints, produced from 1400 to 1600, discussing how artistic practice of imitation and emulation stimulated the development of individual styles. In addition, this course addresses notions of disruptive rivalry, and the representation of slander and envy.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH338H1', 'Art and Consumers in the Renaissance (1400-1700)', '24L', 'It has long been said that the material culture of the Renaissance generated the first stir of consumerism with a variety of artifacts produced from 1400 to 1700 in Italy. This course explores the material culture of Renaissance consumerism and discusses the production and function of works in different art media.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH340H1', '17th-Century Art of the Netherlands', '24L', 'Concentration on the major painters of Holland''s Golden Age, ca. 1580-ca. - 1700. Particular attention is paid to genre painting and the notion of “Dutch realism.” Consideration of art within its social and political contexts. Notions of gender, of the historical past, of embodiment, and of contact with the non-western world will be discussed.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH341H1', 'Venetian Renaissance Art and Architecture', '24L', 'Form and meaning, theory and practice of painting and architecture in Venice, ca. 1450-ca. 1600. Social, political and cultural contexts of making and viewing art, including works by Giorgione, Titian, Veronese, Tintoretto and Palladio.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH345H1', 'The Romantic Movement in French Art', '24L', 'This course explores the painting, sculpture, and graphic arts of the Romantic era in France, from about 1820 to 1850. Major emphasis on Gericault, Delacroix, and Ingres in their artistic, cultural, and political context. Key topics in Romanticism, including Orientalism and gender, are also explored.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH346H1', 'Impressionism', '24L', 'The origin and development of Impressionism in France and Europe, 1860-1886, in its social, political and intellectual context. Painting, graphics and sculpture by Monet, Renoir, Degas, Pissarro, Sisley, Cassatt and Morisot.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH347H1', 'Cubism and Related Movements', '24L', 'An investigation of the birth and development of Cubism, Futurism and Orphism in Europe and North America.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH348H1', 'The Dada and Surrealist Tradition', '24L', 'The origins and development of the Dada and Surrealist movements in early 20th-century Western art, and their lasting impact on art after World War II. Painting, sculpture, graphic arts, and the theoretical preoccupation which accompanied artistic production.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH349H1', 'Abstraction in Twentieth-Century Art', '24L', 'The origins, development, and critical issues pertaining to abstract or non-figurative modes of art as manifested in painting, sculpture and other selected media up to the present time. Movements include European abstract art before World War II as well as post-war developments.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH350H1', 'Minimalism', '24L', 'An investigation of the different definitions and issues of minimal art including seriality, materials, process, objecthood, chance, installation, reception, relations to music and film, and the influence of structuralism.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH352H1', '19th Century Photography', '24L', 'An introduction to the major artists, movements, and debates in photography in Europe and North America, from its prehistory to the turn of the century. Issues considered include the relationship of social class to aesthetics, the role of illusion, the rise of mass reproduction.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH353H1', 'On Display: Cultures of Exhibition, 1789-1900', '24L', 'Examination of the historical development of the cultures of exhibition in Nineteenth-Century Europe, and the diversity of venues displaying works of art and nature. Historical and theoretical overview is complemented by case studies which include investigations of private cabinets of curiosity, encyclopedic museums, commercial galleries, side-shows, and world''s fairs.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH354H1', 'Art in Canada Since the 1960s', '24L', 'An examination of the visual arts in Canada from the 1960''s to the present. A large and diverse range of media, practices, artists, and theoretical contexts will be examined. Emphasis is placed on work that can be seen in the original.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH355H1', 'Landscape to EcoArt', '24L', 'Ecological art is a focus in contemporary global art. We examine ecoart''s antecedents in the landscape genre and Earth Art and the diverse theoretical and disciplinary perspectives that inform our understanding of these movements. Artists include Burtynsky, Eliasson, Long, Mendieta, Netco, Smithson, Turrell. Readings include Deleuze, Heidegger, Latour.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH360H1', 'World of the Senses: Chinese Decorative Arts', '24L', 'This course surveys late imperial Chinese decorative arts from the Song (960-1127) through Qing (1644-1911) dynasties. It focuses on ceramics/porcelain, textiles, and furniture, attending especially to works in Toronto collections. Students will read primary and secondary sources to learn how decorative arts shaped daily life in imperial China.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH363H1', 'The Mechanics of the Image in China', '24L', 'East Asian images differ from Western ones in material support, format, and technologies of image-making. This course probes how East Asian images -- painting on objects, handscrolls, prints, optical media, film, and new media – work.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH364H1', 'Visual South Asia', '24L', 'An overview of the visual culture (monuments to films) of South Asia form the Indus Valley Civilization (3500 BCE) to the contemporary. Focus on visual literacy, stylistic evolution, major concepts and the first-hand study of objects.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH370H1', 'European Renaissance Architecture', '24L', 'Architecture and architectural theory ca. 1400 – ca. 1600.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH371H1', 'Architecture and Urbanism in Baroque Europe', '24L', 'Architecture studied through its various building types and in its urban context. Themes include architecture and power under Absolutism, and the rise of the modern city.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH373H1', 'Modern Architecture Since 1890', '24L', 'In-depth examination of the modern movement in architecture, with particular focus on European avant-gardes of the early twentieth century. Emphasis on close reading of buildings, architectural research methods, and writing skills.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH380H1', 'Special Topics in Art History', '24L', 'The study of various aesthetic, cultural, social, political, and theoretical aspects of art and photography across the centuries.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH381H1', 'Problems in Jewish Art', '24L', 'This course investigates the changing definition of Jewish art and the status of Jewish artists. Other issues explored include Jewish-Christian visual polemics, the construction of individual and communal Jewish identity through art, architecture, and texts, and the conceptual transformation of Jewish craft and ritual objects into art.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH382H1', 'Art Writing', '12L/12P', 'Study and practice in the variety of writing genres and styles associated with art history and contemporary criticism. Students will develop skills in writing for museum exhibitions and publications, reviews and criticism, academic analysis, and writing for popular print and media. Regular and frequent writing assignments. Recommended for FAH majors and specialists.', 'VPHC54H3', 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH388H1', 'Art History Theories and Practices', '24L', 'Investigates the development of art and architectural history as an academic discipline and method of analysis including discussion of varied approaches such as formalism, connoisseurship, post-colonialism, feminism, queer studies, psychoanalysis, and material studies. The course explores the relationship of art history to other disciplines including archaeology, literary criticism, film studies, and anthropology. Suggested for all Specialists and students considering graduate study in art history.', 'FAH388H5', 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": "FAH"}]}'::jsonb),
    ('FAH390Y0', 'Studies Abroad in Spanish Art and Architecture', '24L', 'Through site visits and local resources, this course looks at the history of Spanish art and architecture, including the various work created by the diverse religious and political groups of the Iberian peninsula. The specific focus of the course may vary from year to year.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH391Y0', 'Studies Abroad in Ancient Art and Architecture', null, 'Studies Abroad in Ancient Art and Architecture. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH392Y0', 'Studies Abroad in Medieval Art and Architecture', null, 'Studies Abroad in Medieval Art and Architecture. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH393Y0', 'Studies Abroad in Renaissance and Baroque Art and Architecture', null, 'Studies Abroad in Renaissance and Baroque Art and Architecture. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH394Y0', 'Studies Abroad in Modern and Contemporary Art and Architecture', null, 'Studies Abroad in Modern and Contemporary Art and Architecture.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH395Y0', 'Studies Abroad in Canadian Art and Architecture', null, 'Studies Abroad in Canadian Art and Architecture. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH396Y0', 'Studies Abroad in Asian Art and Architecture', null, 'Studies Abroad in Asian Art and Architecture. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH397Y0', 'Studies Abroad in Architectural History', null, 'Studies Abroad in Architectural History. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FAH399H1', 'Research Opportunity Program', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH399Y1', 'Research Opportunity Program', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH401H1', 'Aegean Wall Paintings', '24S', 'Investigation of the wall-paintings of the Minoan, Cycladic and Mycenaean worlds in the second millennium BC: context, associations, viewing and historical interpretations.', null, 1, '{"operator": "AND", "items": ["FAH206H1", {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH402H1', 'Palaces of Minoan Crete', '24L', 'Around 2000 BC, the island of Crete sees the emergence of what are arguably the earliest towns and states in European prehistory. At the heart of this new social order are the so-called ''palaces'', massive architectural complexes usually interpreted as seats of administrative and political authority. However, fresh discoveries over the past two decades, coupled recently with radical new interpretations, require a fundamental rethinking of the nature of the palaces and their role in Minoan society. This course will provide students with an active opportunity to learn about the latest developments in Minoan art, architecture, and archaeology.', 'FAH423H1', 1, '{"operator": "AND", "items": ["FAH206H1", {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH405H1', 'Understanding Dionysos: The God of Wine, Theatre and the Afterlife', '24S', 'The Greek god Dionysos presents a multifaceted entry point into exploring Ancient Greek art, culture, religion and history. This course is a comprehensive exploration of the figure of Dionysos, from his obscure pre-historic beginnings of foreign origin, to his transformation into other post-classical entities, spanning Christianity to Buddhism. A substantial part of the course deals with his representations in Greek art, and the god''s relationship to the Greeks as the governing figure of many important facets of their lives: drinking practices, sexuality, the performative arts, and the transition into the afterlife through the notion of eternal bliss. The course reading draws on art historical literature, as well as primary sources, and theoretical texts regarding religion and cultural practices.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH307H1", "FAH310H1", "FAH311H1", "FAH312H1", "FAH313H1", "FAH314H1"]}, {"credits": 0.5, "department": "FAH"}]}'::jsonb),
    ('FAH406H1', 'Cross-Cultural Issues in Ancient Art Beyond Greece and Rome', '24S', 'When cultures collide, they assimilate, they exchange, they transform, and they develop, and there seems to be a pattern of recognizable centres of power around which artistic tradition often revolves. This has caused the conventional understanding of certain flowering of artistic heritage as a product of cross-cultural influences. This course is a seminar style survey that explores these fascinating amalgams of artistic traditions that lie at the Eastern outskirts of the Hellenistic world throughout the roman Period, from Bactria to India, and with a heavy focus on the Buddhist art of Gandhara, reaching out along the Silk Road. As the title suggests, the class aims at a renewed framework that re-evaluates the role of the Ancient West, which has been absent since the heavily Eurocentric scholarship from the early 20th century. It also aims to familiarize students with current theoretical issues surrounding cross-cultural studies as it pertains to the visual arts, touching upon modern postcolonial theories of space.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH307H1", "FAH310H1", "FAH311H1", "FAH312H1", "FAH313H1", "FAH314H1"]}, {"credits": 0.5, "department": "FAH"}]}'::jsonb),
    ('FAH407H1', 'Studies in Roman Painting and Sculpture', '24S', 'Issues explored might cover Republican and Imperial painting; its Hellenistic sources and parallel media (mosaic, relief). The four distinctive genres of Roman sculptural production: the portrait, the historical relief, sarcophagi, and replicas of famous Greek sculptures. Styles, themes and modes of display in cultural context.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH205H5", "FAH207H1"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH415H1', 'History of Islamic Cairo', '24S', 'This seminar explores the architectural and urban development of Islamic Cairo (al-Qahira) between the 7th and 16th centuries. As a nexus of both the Islamic empire and the Mediterranean world, Cairo provides an opportunity to explore a major Islamic Medieval city. Modern day Cairo emerged first as a provincial capital (al-Fustat and later al-Qata''a) in the 7th and 8th century and later morphed into a capital under successive dynasties from the 9th to the 16th century. Exploring Cairo throughout this critical historical period, one of both relative stability and upheaval during the post-conquest period to the Crusades, allows for a better understanding of the reciprocity between architecture and urbanism on the one hand and broader political shifts on the other. A central organizing theme of this course is Cairo''s position as a place of multiplicity and confessional diversity, embedded within networks of cultural and economic exchange. Other themes explored include the role played by ceremonies and processions on urban form and the development of public space as well as the development of various religious, charitable, military and educational institutions and their impact upon shaping the city.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH420H1', 'Studies in Western Medieval Art and Architecture', '24S', 'In-depth examination of monuments and issues in the art and architecture of Western Europe from the sixth to the fifteenth century.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH215H1", "FAH215H5", "FAH216H1", "FAH216H5", "FAH265H1", "VPHB53H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH421H1', 'Studies in Medieval Cities', '24S', 'A focused examination of urbanism, art and architecture of a specific medieval city, such as Jerusalem, Rome, Constantinople, or Paris.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH215H1", "FAH216H1", "FAH265H1", "FAH285H5", "VPHB53H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH424H1', 'Studies in Medieval Book Illumination', '24S', 'A consideration of individual types of books, their decoration, function, and cultural context. Topics might include, for example, Gospels, Psalters, or Books of Hours.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH215H1", "FAH215H5", "FAH216H1", "FAH216H5", "FAH265H1", "VPHB53H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH430H1', 'Pieter Bruegel', '24S', 'The study of Pieter Bruegel''s works in the context of Netherlandish culture. Emphasis on secular works.', null, 1, '{"operator": "AND", "items": ["FAH331H1"]}'::jsonb),
    ('FAH433H1', 'Leonardo and His Legacy in Renaissance Italy', '24S', 'This seminar examines major critical developments in the interpretation of High Renaissance art in Italy by looking at key works produced by Leonardo, his contemporaries, and followers (1470-1530).', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH230H1", "FAH274H5"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH434H1', 'The First Art Historians', '24S', 'In Vasari''s Lives of the Artists and their “after-lives,” painters and humanists explored questions of word and image, art and life, biography and history, the psychology of style, the economics and politics of art and the languages of art. How and why did art history originate?', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH230H1", "FAH231H1", "FAH274H5", "FAH279H5", "VPHB64H3", "VPHB74H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH436H1', 'Italian Renaissance Art, Fashion, and Material Culture', '24S', 'This seminar explores fashion in the visual and material culture of Renaissance Italy. It focuses on the discourse of fashion as represented by Renaissance artists in their works and as treated in contemporary texts. It further examines the multiple meanings of dress in the courts of Renaissance Italy.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH230H1", "FAH231H1", "FAH274H5", "FAH279H5", "VPHB64H3", "VPHB74H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH438H1', 'History of Bad Art from Gothic to Kitsch', '24S', '"Bad" art is a critical category that shadows and defines "good" art. How has the art of invective shaped the histories of art by applying ethical, psychological and anthropological values to the world of art? Topics include blasphemy, decadence, senility, the "other" and anti-social behaviors. Special attention will be given to such prejudicial period styles as Gothic, Mannerism, Baroque and Rococo, and to such artistic movements as the Macchiaioli, neo-Kitsch, Dada, Automatism and Degenerate Art. Readings range from Seneca and Vitruvius to Walter Benjamin and Clement Greenberg. Case studies of artists range from Caravaggio to Odd Nerdrum.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH439H1', 'Studies in Renaissance and Baroque Art and Material Culture', '24L', 'Focused examinations of themes and methods in the study of Renaissance and Baroque visual arts and material culture.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH230H1", "FAH231H1", "FAH274H5", "FAH279H5", "VPHB64H3", "VPHB74H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH440H1', 'Dutch Genre Painting of the 17th Century', '24S', 'Study of so-called “scenes of everyday life.” Special attention given to cultural context and problems of constructions of gender and gendered relationships, of social and economic interests, of class conflict, of the relationship with broader European culture. Considerable attention will be paid to the work of Jan Vermeer.', null, 1, '{"operator": "AND", "items": ["FAH340H1"]}'::jsonb),
    ('FAH446H1', 'Arctic Anthropocene? Image Cultures of Arctic Voyaging', '24S', '''Arctic Anthropocene'' examines the extensive visual culture of voyages in the Arctic in the long 19th century. We will probe both Western and Inuit perspectives on the search for the Northwest Passage, whaling, and scientific understandings of the exotic meteorological, human, and animal phenomena of this region through its complex image culture. To underscore ecological understandings of the Arctic in the 19th century and today, we will frame our investigation of the visual culture of this place and time with an interrogation of the notion of the ''Anthropocene.''', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH352H1", "FAH353H1", "FAH354H1", "FAH355H1"]}, {"credits": 0.5, "department": "FAH"}]}'::jsonb),
    ('FAH447H1', '19th-Century Landscape Painting', '24S', 'Investigation of English, French, German and Swiss landscape painting from the birth of the Romantic movement to Post-Impressionism.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH245H1", "FAH287H5", "VPHB58H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH448H1', 'International Art Since 1940', '24S', 'Developments in the mainstream of Western painting and sculpture since World War II with special emphasis upon interrelations between Europe and North America.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH246H1", "FAH289H5", "VPHB59H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH449H1', 'Contemporary Art Movements', '24S', 'Selected aspects of the complex array of international contemporary art movements, their artists, objects, and critical discourses. Potential issues include the theoretical, philosophical, and political concerns addressed by given artworks and artists; the role of art journals, the private patron, and museum display.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH246H1", "FAH289H5", "VPHB59H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH451H1', 'Studies in Black Art', '24S', 'This Seminar explores the work of Black artists from across the African Diaspora, attending to questions such as formal innovation, sociopolitical and historical context, and methodological problems for art historical research.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH101H1", "FAH102H1"]}, {"credits": 0.5, "department": "FAH"}]}'::jsonb),
    ('FAH452H1', 'Contemporary Indigenous Art in Canada and the United States', '24S', 'This course focuses on Indigenous artists working both within and outside of contemporary art spaces in Canada and the United States, through a study of key exhibitions and movements in the Indigenous arts community from 1984 to the present. From the Columbus Quincentennial in 1992 and its echoes in the "Canada 150" celebrations, to artists working from the front lines of land protection movements, we will explore ideas of nationalism, inclusion, intervention, and ''decolonization'' of the gallery.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH457H1', 'Issues in Canadian Art, ca. 1900-1940', '24S', 'Focused, thematic examinations of the visual arts in Canada in the first half of the twentieth century.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH248H1", "FAH292H5"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH458H1', 'Issues in Recent Canadian Art', '24S', 'Focused, thematic examinations of the visual arts in Canada from c. 1960 to the present.', null, 1, '{"operator": "AND", "items": ["FAH354H1", {"credits": 0.5, "department": "FAH"}]}'::jsonb),
    ('FAH461H1', 'East Asian Art as a Cultural System', '24S', 'Methodologically-focused seminar engaged with recovering and articulating in Western terms indigenous ways of seeing and thinking about East Asian art.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH260H1", "FAH262H1", "VPHB73H3", "VPHB77H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH463H1', 'Materiality, Objecthood, Connoisseurship and Collecting in the Arts of East Asia', '24S', 'Seminar based on firsthand examination of East Asian objects in Toronto collections that attends to the historical processes by which such objects were valued and collected.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH260H1", "FAH262H1", "VPHB73H3", "VPHB77H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH464H1', 'Transregional East Asian Art', '24S', 'In-depth examination of the play of East Asian Art within and beyond East Asia.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH260H1", "FAH262H1", "VPHB73H3", "VPHB77H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH465H1', 'Exhibiting China', '24S', 'This seminar teaches students the skills required to curate an exhibition of Chinese materials. Working firsthand with objects of Chinese art and visual culture in local Toronto collections, students learn to document the object, assess authenticity, write object labels, panel texts, and catalogue essays. Students will thus prepare an exhibition, actual or virtual, of Chinese objects in local collections.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH260H1", "FAH262H1", "VPHB73H3", "VPHB77H3"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH470H1', 'Studies in Renaissance and Baroque Architecture', '24S', 'An in-depth study of themes and problems in architecture in Renaissance and Baroque Europe.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH370H1", "FAH371H1"]}, {"credits": 0.5, "department": "FAH"}]}'::jsonb),
    ('FAH472H1', 'Studies in Modern Architecture', '24S', 'Focused examination of themes and methods in the history of architecture since 1750.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FAH270H1", "FAH272H1", "FAH273H1"]}, {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH473H1', 'Studies in Canadian Architecture and Landscapes', '24S', 'An in-depth study of themes in the history of architecture and landscape in Canada.', null, 1, '{"operator": "AND", "items": ["FAH273H1", {"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH480H1', 'Special Topics in the History of Art and Architecture', '24L', 'Focused examination of special topics in the art and architecture of any period in the Mediterranean, Europe, North America, Asia, or other global regions.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH481H1', 'Internship', '24S', 'The internship is designed to offer hands-on experience pertaining to the study, exhibition, and care of works of art, focused on the collections and activities of the University Art Centre, an auction house, a public museum, or a private gallery. Students must provide proof of their acceptance as an intern by the Art Centre/auction house/museum/gallery in order to be enrolled in the course. This course is Pass/Fail. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH481Y1', 'Internship', '48S', 'The internship is designed to offer hands-on experience pertaining to the study, exhibition, and care of works of art, focused on the collections and activities of the University Art Centre, an auction house, a public museum, or a private gallery. Students must provide proof of their acceptance as an intern by the Art Centre/auction house/museum/gallery in order to be enrolled in the course. This course is Pass/Fail. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH483H1', 'Introduction to Conservation: Materials, Deterioration, and Preservation in Art and Material Culture', '24S', 'An introduction to conservation, designed to give students a basic understanding of the field, its techniques, and its purposes. Sessions conducted by specialists in the Royal Ontario Museum conservation department.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH484H1', 'Fashion & Textiles: Culture & Consumption', '24S', 'This course examines the history, meaning and consumption of Western European fashion (18th - 21st centuries). Analysis and research will combine student seminars with the study of actual artefacts in the Textile & Costume Collection of the Royal Ontario Museum.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH485H1', 'Collecting Canada: Canadian Pictorial Arts Collection at the Royal Ontario Museum', '24S', 'Theoretical and practical engagement with the ROM''s Canadian paintings, prints and drawing collections (18th-20th C). Through lectures, workshops, and seminars, we consider the collecting, interpretation, and display of images within the framework of “documentary art” and its various connotations.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH486H1', 'Case Studies at the Royal Ontario Museum', '24S', 'In-depth investigation of objects at the Royal Ontario Museum. Content will vary according to the museum department offering the course in any given semester.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH487H1', 'Introduction to Asian Textiles', '24S', 'Introduction to the diverse textile traditions of Asia and the diverse means for interpreting them, with a concentration on core production areas, select regional traditions and connecting forces. Includes first-hand study of objects in ROM collections and galleries and possible guest lectures.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH488H1', 'Considering Sustainable Textiles and Fashions in the Age of Climate Crisis', '24S', 'This seminar looks at historic and contemporary global thinking about the production and consumption of textiles and fashions within the current climate change crisis, and over-production due to fast fashion. We question the notion of "in" and "out" of Western seasonal style and look at historic models to understand new economies of scale and value, issues of labour and natural resources. Through lectures, workshops, and seminars, the class will consider how to harness past models to attain the future of textiles and fashion and the context surrounding the 3 R''s, reduce, reuse and recycle.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH490H1', 'Introduction to the Textile Arts of the Indian Ocean World', '24S', 'The Indian Ocean has been called the Cradle of Globalization. For thousands of years monsoon winds linked the people and arts of this vast Ocean that stretches from East Africa in the West to Indonesia (and beyond) in the East. Throughout its long history, handwoven textiles have been amongst the area''s greatest art forms, trade goods, religious objects and markers of identity. This course will survey the wide variety of these forms, from c. 1100 to 1950. Special attention is placed on India, which lies at the center of the region, and originated many of the fibres, techniques, design and iconography of the wider area. Select regional manifestations are then examined in depth, using the ROM''s extensive collections. These range from the silks of Madagascar, to embroidered men''s wear of Oman, to the cosmopolitan batiks of northern coastal Java. It is seen that all these traditions can best be understood within the framework of the wider Indian Ocean region.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH494H1', 'Independent Studies', null, 'Eligible students may undertake an independent study course under the supervision of Department of Art History (St. George campus) faculty member. Refer to the Art History website for further information and application instructions. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FAH494Y1', 'Independent Studies', null, 'Eligible students may undertake an independent study course under the supervision of a Department of Art History (St. George campus) faculty member. Refer to the Art History website for detailed information and application instructions. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "FAH"}]}'::jsonb),
    ('FCS194H1', 'Urban Youth Languages of the World', '24S', 'Are there such phenomena as urban youth “languages”? How do they evolve and what commonalities or divergences are there? In this course, we will survey a range of urban youth languages that have emerged in African, North American and European contexts – with specific focus on their structural (linguistic) and social typicalities. Discussions and presentations will focus on the sociolinguistic concepts of language contact, bi/multilingualism, lexical innovation/renovation, language mixing, etc. in relation to youth language practices. We will be comparing major varieties of these language practices within and between the continents, and also be assessing their prospects and implications for language change. This course is taught in English. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('FCS195H1', 'French Culture from Napoleon to Asterix', '24L', 'A multi-media course, analyzing the contributions the French have made to world culture in such domains as architecture, art, literature, and music, as well as some of the implications of the appropriation of French cultural icons by big business and the media.', null, 1, null::jsonb),
    ('FCS196H1', 'Historical, Geographic and Social Variation in French', '24S', 'Throughout most of its nearly 1200-year history, the language that we now call French was not a single linguistic entity, but rather a collection of related dialects. Although socio-political factors resulted in a partial unification of these dialects during the 18th and 19th centuries, the unification was, to a large extent, outweighed by French colonization of areas such as North America and Africa, which resulted in even greater linguistic diversification. The purpose of this course is to provide an overview of the extensive variation that exists throughout the French-speaking world. Topics to be covered include phonetics (pronunciation), lexicology (word selection) and morpho-syntax (grammar). This course is taught in English. No knowledge of French or linguistics is required. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('FCS197H1', 'Pleasure, Pain and Nostalgia in Belle Époque', '24L', 'This course will explore ideas and cultural representations of 19th century France through examples from art, philosophy, and literature with an emphasis on the critical discussion of two literary narratives that challenged tradition and authority: Flaubert’s “Madame Bovary” and Maupassant’s “Bel-ami”. The course will be held in English. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FCS198H1', 'The Literacy of Images: Interactions between Text and Other Media', '24L', 'How do images create meaning in texts? How do words guide the interpretation of images? This course will examine relations between texts from different literary genres (the Bande Dessinée, fiction and autobiography) and other media (illustration, photography, cinema) through an interdisciplinary theoretical framework, by combining perspectives from literature, cinema, illustration, and photography. The course will be held in English. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FCS199H1', 'Marketing in the French Speaking World', '24S', 'This course investigates sociocultural and linguistic issues surrounding market expansion and marketing of products and services to French-speaking audiences in Canada and elsewhere. Students consider challenges posed by increased globalization through comparisons of English- and French-speaking communities, while exploring basic marketing theory. Through case studies of successes and failures, students examine how companies develop and adapt branding and messaging for Francophone audiences by integrating differences in humour, values, politics, and financial considerations. Students thus develop an understanding of the Francophone consumer and gain skills for advertising and branding in a Francophone or bilingual environment. This course is taught in English. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('FCS290H1', 'Special Topics in French Cultural Studies I', '24L', 'The relation of French popular culture to society. For more information, see https://www.french.utoronto.ca/course-offerings-2020-2021/french-cultural-studies-courses-fcs.', null, 1, null::jsonb),
    ('FCS291H1', 'Special Topics in French Cultural Studies I', '24L', 'The relation of French popular culture to society. For more information, see https://www.french.utoronto.ca/course-offerings-2020-2021/french-cultural-studies-courses-fcs.', null, 3, null::jsonb),
    ('FCS292H1', 'Love, Sex and Desire in French Literature and Cinema', '24L', 'This online, asynchronous course will explore the themes of love, sex and desire in French literature and cinema through close reading, analysis, and interpretation of three major novels from the eighteenth to the twentieth literature. A comparative approach based on various examples taken from literary, philosophical texts and from film adaptations will examine the concept of love and its many definitions. Selections from ancient and modern philosophical texts on love, sex, and desire will be the starting point of our discussions: Ovid, "The Art of Love", Plato, "The Symposium", Bataille, "Eroticism", Beauvoir, "The Woman in Love", and Foucault, "The History of Sexuality". The course will be taught in English. Students who are proficient in French and intend to complete their readings and major tests in French (Online Essay and Online Film Analysis) in order to count this course towards a program in French (Major or Specialist only), should inform the Course Instructor of their decision by the end of the first week of classes. N.B. Discussion Forum contributions will be submitted in English only.', null, 1, null::jsonb),
    ('FCS310H1', 'French Cinema', '24L/24P', 'Cinema in France with emphasis on theory and practical criticism, on auteurs and movements such as the avant-garde of the twenties and the New Wave of the late fifties. Films shown are subtitled.', 'FCS310Y1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('FCS369Y0', 'The Culture of Touraine', '48L', 'This course will offer a unique opportunity to study the culture of the Touraine region while living an experience of complete immersion in Tours, a city located in the Loire Valley, a UNESCO World Heritage Site and the seat of power of the French monarchy until the 17th Century. Not eligible for CR/NCR option.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('FCS390H1', 'Special Topics in French Cultural Studies II', '24L', 'Studies on an individual writer or specific area of literature. For more information, see https://www.french.utoronto.ca/course-offerings-2020-2021/french-cultural-studies-courses-fcs.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('FCS391H1', 'Special Topics in French Cultural Studies II', '24L', 'Studies on an individual writer or a specific area of literature. For more information, see https://www.french.utoronto.ca/course-offerings-2020-2021/french-cultural-studies-courses-fcs.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('FCS392H1', 'Special Topics in French Cultural Studies II', '24L', 'Studies on an individual writer or specific area of literature. The relation of French popular culture to society. For more information, see https://www.french.utoronto.ca/course-offerings-2020-2021/french-cultural-studies-courses-fcs.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('FIN100H1', 'Elementary Finnish I', '48P', 'The Department reserves the right to assign students to courses appropriate to their level of competence in Finnish. An introductory language course for students with no knowledge of Finnish. The acquisition of a basic vocabulary and of an understanding of elementary structural features through practice in comprehension, speaking, reading and writing.', null, 1, null::jsonb),
    ('FIN110H1', 'Elementary Finnish II', '48P', 'An introductory language course for students with no knowledge of Finnish. The acquisition of a basic vocabulary and of an understanding of elementary structural features through practice in comprehension, speaking, reading and writing.', null, 1, '{"operator": "AND", "items": ["FIN100H1"]}'::jsonb),
    ('FIN200H1', 'Intermediate Finnish I', '48P', 'The four language skills (speaking, listening, reading and writing) honed by discussion of Finnish literary texts as well as by compositions in Finnish about these texts, by a series of conversation exercises, and by analysis of morphology, syntax and word formation. Translation is used to aid in language learning.', 'FIN200Y1', 1, '{"operator": "AND", "items": ["FIN110H1"]}'::jsonb),
    ('FIN210H1', 'Intermediate Finnish II', '48P', 'The four language skills (speaking, listening, reading and writing) honed by discussion of Finnish literary texts as well as by compositions in Finnish about these texts, by a series of conversation exercises, and by analysis of morphology, syntax and word formation. Translation is used to aid in language learning.', null, 1, '{"operator": "AND", "items": ["FIN200H1"]}'::jsonb),
    ('FIN225H1', 'Culture, Society and Politics of the Nordic Region', '24L', 'An introduction to the culture, society and politics of the Nordic region with a focus on Finland, Sweden and Estonia, and including other countries of the Baltic sea region. An overview of the evolution of culture and society, as well as historical and political developments, demonstrating how interactions between these two spheres have shaped life in the region today.', null, 1, null::jsonb),
    ('FIN230H1', 'Finnish Culture 1800 to Present', '12L/12P', 'FIN230H1 offers an introduction to Finnish society, history and culture from 1800 to present. The course examines the rise of Finnish nationalism in the 1800s, its main manifestations, and concentrates on the developments of its cultural, educational and social institutions, its economic structures, demographics, cultural traditions as well as the nation''s bilingual status. The focus is on contemporary themes placed in a wider societal context.', null, 3, null::jsonb),
    ('FIN236H1', 'Hot Reads from a Cool Country: Contemporary Finnish Literature', '24S', 'An introduction to contemporary Finnish literature which leads students through major developments in Finnish literature over the last 30 years with a focus on the major themes and trends of Finnish literature through selected representative works. Finnish texts will be read in translation, analyzed and discussed.', null, 1, null::jsonb),
    ('FIN238H1', 'The Vikings', '48L', 'This course examines the influence and reception of the Vikings on the Nordic countries and Europe up to the modern day, focusing on their legacy in the contemporary Nordic world in literature, film and other cultural fields.', null, 1, null::jsonb),
    ('FIN240H1', 'Masterpieces of Scandinavian Literature', '12L/12S', 'Introduction to the greatest authors of Scandinavian literature and their greatest works, particularly August Strindberg, Henrik Ibsen, H.C. Andersen, Knut Hamsun, Selma Lagerlof, Pär Lagerkvist, Aleksis Kivi, Sigrid Undset and Halldor Laxness, etc. These are situated in their Scandinavian context and in world literature. (Offered every two or three years)', null, 1, null::jsonb),
    ('FIN250H1', 'Finnish Cinema', '12P/24S', 'The course offers a survey of development of Finnish cinema from its parochial beginnings to its international recognition with a focus on contemporary themes. Selected films with different themes and topics will be screened and analysed. Readings and subtitles in English. (Offered in alternate years)', null, 1, null::jsonb),
    ('FIN260H1', 'Scandinavian Cinema', '12P/24S', 'Major developments of cinema in Scandinavia in the 20th and 21st centuries focusing on Denmark, Sweden, and Finland. In addition to "old classics," most important recent films are screened and discussed.  Film directors include Ingmar Bergman, Carl Th. Dreyer, Aki and Mika Kaurismaki, and many others. (Offered in alternate years)', null, 1, null::jsonb),
    ('FIN270H1', 'Modern and Contemporary Finnish Architecture and Design', '24P', 'Finnish architecture and design from the 19th century to the present. Explores the technical and stylistic development of modern architecture and design in relation to the cultural and socioeconomic progress of the young nation. The focus is on the work of modern architects and designers. The course also examines the history of Scandinavian design more broadly.', null, 1, null::jsonb),
    ('FIN280H1', 'Finnish Musical Culture from Sibelius to Heavy Metal', '24S', 'Analyzing the role of music in Finnish cultural identity, history, and society, this course explores both traditional and contemporary Finnish music, concentrating on what makes Finnish musical culture unique: Sibelius, kantele, folk music, heavy metal, rock and pop music. We will explore the themes of national and international music, the music industry, and the globalization of Finland''s music.', null, 1, null::jsonb),
    ('FIN300H1', 'Advanced Finnish I', '12P/24S', 'Advanced Finnish provides a continuation of  FIN210H1 Intermediate Finnish.', null, 1, '{"operator": "AND", "items": ["FIN210H1"]}'::jsonb),
    ('FIN310H1', 'Finnish Folklore: The Kalevala', '12L/12S', 'An examination of the Finnish national epic, the Kalevala: its relationship to the tradition of folk poetry; its quality as an epic poem; the mythological, religious, and cultural dimensions of its world view; its role in Finland''s nation-building in the 19th and 20th centuries. Readings in English. (Offered at least every alternate year)', null, 1, null::jsonb),
    ('FIN320H1', 'The Finnish Canadian Immigrant Experience', '12L/12S', 'Major issues and dimensions of the culture and experience of the Finnish immigrants to Canada, including Finnish Canadian literature, theatre, and press. Conceptual and ideological contributions to working class culture, women''s lives, religious and social attitudes and values. Readings in English. (Offered every three or four years)', null, 3, null::jsonb),
    ('FIN340H1', 'Advanced Finnish II', '12P/24S', 'Advanced Finnish II provides a continuation of  FIN300H1 Advanced Finnish I.', null, 1, '{"operator": "AND", "items": ["FIN300H1"]}'::jsonb),
    ('FIN350H1', 'The Finnish Short Story', '24S', 'Historical, structural, and thematic study of the short fiction of Finland from the Romanticism of the 19th century to contemporary post-structuralism and post-modernism. Works of Runeberg, Topelius, Kivi, Canth, Aho, Jotuni, Lehtonen, Schildt, Sillanpaa, Haanpaa, Meri, Hyry, Salama, Mukka, Liksom, and others. Readings in English. (Offered in alternate years)', null, 1, null::jsonb),
    ('FIN360H1', 'Bilingualism in Finland', '12L/12S', 'Bilingualism in Finland as a case study in the sociology of language. A critical survey of the historical development of language politics in Finland as a bilingual society from 1800 until present.', 'FIN340H1', 3, null::jsonb),
    ('FIN400H1', 'Translation: Finnish-English', '24S', 'Written translation from Finnish to English. Students will apply their textual analysis skills in translating texts drawn from diverse sources and genres, while exploring the general theory of translation. Translation exercises will serve as the basis for training in comparative Finnish-English stylistics.', null, 2, '{"operator": "AND", "items": ["FIN300H1"]}'::jsonb),
    ('FIN415H1', 'Finnish Literature in the 20th Century', '24S', 'This course examines the main literary works and genres of 20th Century Finland, especially Jotuni, Sillanpaa, Haanpaa, Meri, Manner, Linna, Tuuri and a sample of contemporary writers. All readings in Finnish.', null, 1, null::jsonb),
    ('FIN420Y1', 'Independent Study', null, 'A year-long reading and research project of significant depth in a major area in Finnish language, literature or culture approved and supervised by an instructor. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FIN421H1', 'Independent Study', null, 'A semester-long reading and research project of significant depth in a major area in Finnish language, literature or culture approved and supervised by an instructor. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FOR199H1', 'Trees in Architecture and Urban Design', '24L', 'Most depictions of “cities of the future” are a fusion of buildings and forests. Is this happening? If not, why not? This course bridges the disciplines of forestry, architecture, and landscape and urban design to examine the evolving role of trees in human habitations. The course will survey designs incorporating trees on buildings, from the hanging gardens of Babylon to the Bosque Verticale of contemporary Milan, the evolution of urban forestry and urban “green infrastructure”, and history and current policy initiatives and debates. The course will involve site visits and guest lectures in the City of Toronto, readings of both popular and scholarly literature, as well as student design projects and presentations. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('FOR200H1', 'Conservation of Canada''s Forests', '24L', 'Forest conservation issues in Canada; fundamentals of forest biology and ecology; forest biodiversity; development of forest management philosophy in Canadian forested regions; concepts of sustainability. Sustainable forest management strategies; forest policy and economics in a Canadian context; forest certification; protected areas.', null, 4, null::jsonb),
    ('FOR201H1', 'Conservation of Tropical and Subtropical Forests', '24L', 'The world''s major tropical and subtropical forest biomes; prospects for conservation and sustainable management; consequences of different forest development strategies; tropical deforestation and selective logging; agroforestry; biodiversity and non-timber forest products; the fuelwood crisis; large carnivore conservation; ecological, economic and social perspectives.', null, 4, null::jsonb),
    ('FOR300H1', 'Forest Products in Sustainable Forestry', '24L/24P', 'Traditional and non-traditional forest products; wood structure; properties and material attributes; functional characteristics and logistics of wood product industry. Contribution of innovative product development to conservation; adding value; residue use; biorefinery; under-utilized species; wood protection. Forest product certification; eco-labelling; life cycle analysis.', null, 5, null::jsonb),
    ('FOR301H0', 'Field Methods in Forest Conservation', null, 'A practical introduction to the field methods used by forest conservationists in Ontario. The overnight field camp portion is approximately seven days taking place during August. Field exercises will provide students with practical training in tree identification, forest ecosystem classification, forest inventory, stand management prescriptions, tree marking, and silvicultural systems. Each student is required to pay an ancillary fee of approximately $875 to cover the costs of transportation, food, and accommodation. Interested students should contact the Forestry Program Administrator to register. Later registrations will be considered if class size permits.', null, 4, null::jsonb),
    ('FOR301H1', 'Field Methods in Forest Conservation', null, 'A practical introduction to the field methods used by forest conservationists in Ontario. The overnight field camp portion is approximately seven days taking place during August. Field exercises will provide students with practical training in tree identification, forest ecosystem classification, forest inventory, stand management prescriptions, tree marking, and silvicultural systems. Each student is required to pay an ancillary fee of approximately $875 to cover the costs of transportation, food, and accommodation. Interested students should contact the Forestry Program Administrator to register. Later registrations will be considered if class size permits.', null, 4, null::jsonb),
    ('FOR302H1', 'Societal Values and Forest Management', '24L', 'This course will explore the diverse societal values, interests, and perspectives that informs forest management in rural and urban settings. It will examine the social and political environment in which forest management takes place, and the different approaches to balancing social, economic, and environmental objectives in forest management. Topics include Indigenous stewardship and traditional ecological knowledge, climate change, ecosystem services, urban forestry, community forestry, recreation, human health and well-being, biodiversity conservation, equity and environmental justice, and adaptive management.', null, 3, null::jsonb),
    ('FOR303H1', 'Human Dimensions of Global Forests', '24L', 'Global forest resources and forest economics; relationships between societies and forests, consumption, trade and valuation of timber and non-timber products; ecosystem services, climate change and forestry, tropical deforestation and softwood lumber dispute.', null, 3, null::jsonb),
    ('FOR305H1', 'Biology of Trees and Forests', '24L/40P', 'An overview of the biology of trees and the ecological principles that govern the structure and function of forests. Topics in tree biology will include tree identification, wood anatomy, tree architecture, resource acquisition and allocation, tree growth and mortality. Topics in forest ecology will include resource competition, stand development, species succession, and the cycling of nutrients and energy. This course will include a substantial field and lab component.', null, 4, null::jsonb),
    ('FOR306H1', 'Tropical Forest Ecology and Conservation Field Course', '24P', 'This course will provide practical experience in tropical forest conservation, introducing tools for rapid assessment of biodiversity, analysis of human use and natural disturbance impacts on forest structure and diversity, and the development of effective forest conservation strategies. See Forestry website for details. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": ["FOR201H1", {"operator": "OR", "items": ["FOR301H1", "FOR305H1"]}]}'::jsonb),
    ('FOR307H1', 'Forest Insect Ecology & Management', '24L/24P', 'Insect identification and ecology, biodiversity and conservation, invasive species, insect-tree interaction, biological control, pesticide use, and integrated pest management.', null, 4, null::jsonb),
    ('FOR310H1', 'Bioenergy from Sustainable Forest Management', '24L/12T', 'Socio-economic, technical, political and environmental issues associated with the utilization of forest biomass (e.g., harvesting residues, thinnings, salvage, short rotation woody crops) for a source of renewable energy.', null, 3, null::jsonb),
    ('FOR400Y1', 'Advanced Seminar in Forest Conservation', '48S', 'Examination of current and emerging critical issues affecting sustainable management and conservation of global forests. Seminars led by students, faculty and visiting speakers.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FOR200H1", "FOR201H1"]}, {"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FOR300H1", "FOR301H1", "FOR302H1", "FOR303H1", "FOR305H1", "FOR306H1", "FOR307H1", "FOR310H1"]}]}'::jsonb),
    ('FOR401H1', 'Research Paper/Thesis in Forest Conservation', null, 'A research project requiring the prior consent of a member of the Department to supervise the project. Individual in-depth student research projects on significant forest conservation and forest biomaterial issues, based on field and/or laboratory research, or literature survey. Not eligible for CR/NCR option. Please contact Program Administrator for further enrollment details.', null, null, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FOR300H1", "FOR301H1", "FOR302H1", "FOR303H1", "FOR305H1", "FOR306H1", "FOR307H1", "FOR310H1"]}]}'::jsonb),
    ('FOR403H1', 'Directed Readings', '24S', 'Requires the prior consent of a member of the Department to supervise the readings and assignments. Provides opportunities for students to carry out an individual in-depth study of current forest conservation and forest biomaterials issues. Please contact the Program Administrator for further enrollment details. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FOR300H1", "FOR301H1", "FOR302H1", "FOR303H1", "FOR305H1", "FOR306H1", "FOR307H1", "FOR310H1"]}]}'::jsonb),
    ('FOR404H1', 'Arboriculture', '24L', 'The management and care of individual trees in the places we live, work, and play, from rural communities to urban centres, is critical to protecting human life and property, and to maximizing the many social, environmental, and economic benefits that trees provide. Students will develop a professional level of knowledge and skills in arboriculture expected of tree care professionals like arborists and urban foresters, including: tree biology, tree identification and selection, soil management, installation and establishment, pruning, diagnosis and treatment, trees and construction, tree risk management, safe work practices, and urban forestry. Emphasis will be placed on application, real-world scenarios, and problem-based learning. Professionalism, ethics, career pathways and professional development will also be covered.', null, 4, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('FOR410H1', 'Bioenergy and Biorefinery Technology', '24L/24T', 'Technological advances and approaches in deriving biofuels and chemical feedstocks from forest and other biomass. Fundamental chemical attributes of biomass, as they affect the fuel value and potential for deriving liquid, solid and gaseous fuels and valuable chemicals for other applications will be discussed.', 'FOR425H1 (APSC)', 5, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('FOR413H1', 'Wildlife Ecology & Conservation', '24L', 'Temperate and tropical wildlife ecology and conservation; roles of wildlife in forest conservation; impacts of forestry practices and landscape modification on wildlife; ecology and viability of wildlife populations; human uses and abuses of game and non-game species.', 'EEB255H1,  EEB365H1', 4, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FOR300H1", "FOR301H1", "FOR302H1", "FOR303H1", "FOR305H1", "FOR306H1", "FOR307H1", "FOR310H1"]}]}'::jsonb),
    ('FOR416H1', 'Green Urban Infrastructure', '24L', 'Trees in and around the city are key to providing multiple engineered and ecological services that only recently have been brought into the responsible fiscal planning of every municipality around the globe. Reviews the role of trees and woodlands in providing environmental, social and economic benefits to urban and peri-urban residents and to the broader environment. Examines approaches to the characterization of urban forest ecosystems, and their planning and management.', 'FOR421H1 (APSC)', 4, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('FOR417H1', 'Agroforestry', '24L', 'This course explores the roles of trees and forests in agricultural land-use systems and examines the biological and management aspects of agroforestry. The sustainability of agroforestry systems is examined within the context of socio-economic constraints, geopolitical forces, and Indigenous perspectives.', null, 4, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('FOR418H1', 'Urban Forest Conservation Field Camp', '45L/15P', 'A ten-day field course examining urban forestry issues in the GTA, southern and eastern Ontario and Quebec. Topics include: urban forest inventories, nursery production, arboricultural techniques, urban woodland management, urban forest health, urban forest administration, urban dendrology, and urban forestry research. Additional fees for field course (e.g. accommodation, food, other within course travel expenses) will apply. See Forestry website for details. Not eligible for CR/NCR option.', null, 4, '{"operator": "OR", "items": ["FOR200H1", "FOR201H1"]}'::jsonb),
    ('FOR419H1', 'Forest Fire Behaviour and Management', '24L/24P', 'Understanding forest fire activity is important for predicting fire''s impact on forests and the wildland-urban interface, as well as understanding the impacts of climate change. Basic principles of forest fuel moisture exchange, fire occurrence and fire behaviour are explored. Emphasis is placed on application of these models to real fire management problems.', null, 4, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('FOR420H1', 'Green Process Chemistry', '24L/12T', 'This course provides an overview of the chemistry of wood and wood materials involving cellulose, hemicellulose, lignin, extractives. It also covers some reaction chemistry associated with these chemical components.', null, 5, null::jsonb),
    ('FOR423H1', 'Sustainable Materials Design and Manufacturing', '24L/24T', 'This course focuses on the manufacturing processes, properties and uses of wood and agricultural fibre based products including wood based composites, ligno-cellulosic/thermoplastic composites and structural or engineered composites, and the practical use of these products in design.', 'FOR424H1 (APSC)', 4, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('FOR426H1', 'Working with Wood', '24L/3T/6P/3S', 'Wood has been an important building material throughout the ages and in today''s world has taken on the added importance of being a renewable and sustainable material that assists with greenhouse gas mitigation strategies. This course will provide students with an understanding of wood''s unique physical properties, the variability of these properties within different species and how these properties can inform its proper use in various applications. The Canadian forestry industry sets the context for this course acknowledging that forests transcend political borders and reach around the world.', null, 5, null::jsonb),
    ('FRE210H1', 'Introduction to Québec Literature and Culture', '24L/12T', 'An introduction to various aspects of Québec literature and culture through the study of literary texts, cinema, and artistic productions, and their role in the evolution of a distinct Québec society. The course also familiarizes students with important socio-cultural and political events, which participated in the evolution of Québec society and provide a better understanding of Québec literature.', null, 1, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FRE245H1', 'Introduction to French Cultural and Literary Studies', '24L/12T', 'This course is a practical introduction to concepts, methods and problems of literary analysis as well as an overview of French artistic culture. Using elements of comparison from fine arts, contemporary and popular culture (including novels and movies) and a variety of emblematic works of French and Francophone literatures (among others: essays by Voltaire, Montesquieu and Simone de Beauvoir; poems by Ronsard, Hugo, Baudelaire and Césaire; excerpts from novels by George Sand, Albert Camus and Patrick Chamoiseau), its objective is to provide students with a practical introduction to the tools of literary analysis, but also to help them better read, understand and appreciate literary texts.', 'FRE240H1', 1, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FRE246H1', 'Introduction to French Literary Analysis', '36L', 'This course provides a general introduction to French and francophone literature of different genres and periods. Special emphasis will be placed on concepts, methods, and problems of literary analysis with the goal of helping students to improve their ability to write literary essays. Among the questions to be explored are: What are the rules and conventions of scholarly writing? How does one develop and structure arguments to ensure that a paper is well organized? How are rhetorical devices analyzed? When and how should bibliographical references be inserted?', 'FRE241H1', 1, '{"operator": "AND", "items": ["FRE245H1", {"operator": "OR", "items": ["FSL224H1", "FSL225H1", "FSL320H1"]}]}'::jsonb),
    ('FRE272H1', 'The French Language: A Linguistic Introduction', '24L/12T', 'A general introduction to the structure of French language, from a linguistic perspective. Students will become acquainted with the various components of the language (sound, meaning, word formation, sentence structure) through detailed description and basic analysis of Canadian and European varieties of French. Students will also be introduced to the study of French in the context of bilingualism (second language acquisition, sociolinguistics). This course is mandatory in all specialist and major programs.', null, 2, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FRE273H1', 'Introduction to the History of the French Language', '24L/12T', 'A discovery of a long and fascinating history, stretching from the spoken Latin of the Gauls to the many varieties of French found today all over the world via the investigation of the social, political, and cultural causes of language change. Our focus includes topics such as medieval bilingualism, the regulation of language through the Académie française, the political use of the French language, the emergence of the Francophonie and modern Canadian French.', null, 2, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FRE274H1', 'Introduction to the Linguistic Analysis of French', '24L/12T', 'An analytical study of contemporary French phonetics and phonology, morphology, syntax and semantics. This course is designed to prepare students for more advanced study of French linguistics at the 300 and 400 levels.', null, 2, '{"operator": "AND", "items": ["FRE272H1", {"operator": "OR", "items": ["FSL224H1", "FSL225H1", "FSL320H1"]}]}'::jsonb),
    ('FRE299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb)
